quests[13601] = { id = 13601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Aid of the Refugees", description = "By Elune!  It appears that many of those we feared dead from the attack on old Auberdine have taken refuge in a camp outside the town ruins.\n\nThe cultists at the Twilight Encampment were planning on making quick work of them.  It's a good thing that you successfully attacked their position.\n\nSeek out Priestess Alinya at the Refugee Camp east of old Auberdine and far south of here.", sourceObjective = "Sentinel Lendra at Lor'danel wants you to speak to Priestess Alinya at the Refugee Camp.", completion = "I thank you for coming to our assistance.  As you can see, the refugees' situation is dire.", sourceObjectiveStatus = "unverified-source-field" }
quests[13602] = { id = 13602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga of the Strand", description = "There is evil lurking on the coast to the west.\n\nThe Zoram Strand is the resting place of the doomed city of Zoram, destroyed during the Sundering and submerged beneath the seas. It has been lost to the night elves for ages. Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know. But reason matters little; we must slay these fiends and throw them back to the depths!", sourceObjective = "Slay any 15 Wrathtail naga at the Zoram Strand.", completion = "Very well done, {name}. Your actions in the Zoram Strand against the naga are commendable.\n\nI know your feat was not easily accomplished, for the strength and guile of the naga is well known to the night elves. We know this, for we share a history with them.\n\nThe naga are cursed Highborne night elves. Ten thousand years ago, Queen Azshara made a pact of desperation with the Old Gods to save her surviving people from a watery grave.\n\nThe naga are the result of that pact.", sourceObjectiveStatus = "unverified-source-field" }
quests[13603] = { id = 13603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Marshal Jacob Alerius at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13604] = { id = 13604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivum Data Disc", description = "This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections.  Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\"\n\nThere must be a device inside Ulduar capable of reading the disc.", sourceObjective = "Bring the Archivum Data Disc to the Archivum Console in Ulduar.", progress = "The console whirrs with energy as the round receptacle opens.", completion = "The platinum disc fits perfectly inside the console.  It begins to spin as its contents are scanned by white beams of light.", sourceObjectiveStatus = "unverified-source-field" }
quests[13605] = { id = 13605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Refugee", description = "There was this massive earthquake and then everything went black. The next thing I know, I woke up here a prisoner. The whole place is overrun with air elementals!\n\nI hope that everyone's okay. These Twillight's Hammer scum better not have hurt any of my friends!\n\nQuick, {class}, use something sharp to jimmy the lock on this ball and chain. Together we should be able to make it to the refugee camp.", sourceObjective = "Escort Archaeologist Hollee to safety", completion = "Aye, you're the fine lad who saved my Hollee!\n\nWell, I've got a fitting reward for you here, I'm sure. We really can't thank you enough for bringing her to safety, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13606] = { id = 13606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freya's Sigil", description = "Freya's Sigil is going to be one of the tougher ones, I reckon.\n\nAccording to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark.  Should any of the elders be harmed, the Sigil's integrity will be compromised.\n\nSparing the elders, however, means that Freya will be more powerful when you face her.\n\nWhat can I say, {name}.  We're stuck between a rock and hard place.", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to obtain Freya's Sigil.\n\nFor more information on obtaining Freya's Sigil consult the Archivum Console.", progress = "Freya's sigil, {name}?  Do ye have it?", completion = "Excellent job, {name}.  We're one step closer to saving Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[13607] = { id = 13607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Celestial Planetarium", description = "Listen, <lad/lass>!  Azeroth's fate is at stake here.\n\nOur only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters.\n\nLocate the Celestial Planetarium and come back with any information you get.  We might still have some time to prepare for Algalon's arrival.", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to locate the entrance to the Celestial Planetarium.", progress = "Did you find it, {name}?", completion = "It's locked?  Figures!\n\nLet's see what information this junk heap can give us...", sourceObjectiveStatus = "unverified-source-field" }
quests[13609] = { id = 13609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodir's Sigil", description = "Hodir's Sigil won't be easy to obtain.  Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it!\n\nCheck the Archivum console if you need more information.  That thing contains more knowledge than all of the world's libraries put together!", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to obtain Hodir's Sigil.\n\nFor more information on obtaining Hodir's Sigil, consult the Archivum Console.", progress = "Did ye obtain the sigil, {name}?", completion = "Ye did it!  I don't know how, but ye did!", sourceObjectiveStatus = "unverified-source-field" }
quests[13610] = { id = 13610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorim's Sigil", description = "Thorim's not himself, {name}.  He's come under a dark influence.\n\nAn evil presence under the guise of an illusion pretends to be his lost wife, Sif.\n\nYe can't let him be overcome by this impostor's spell.  If he does, the location of his sigil might forever be lost!\n\nYer going to have to beat some sense into him and yer going to have to do it quick.\n\nAs always, the Archivum Console will give ye all the gory details... even the ones ye don't like.", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to obtain Thorim's Sigil.\n\nFor more information on obtaining Thorim's Sigil consult the Archivum Console.", progress = "Well, {name}?  Do ye have it?", completion = "Ye never cease to impress, {name}.\n\nYe and me are having a pint together after all this is done, ye hear me?", sourceObjectiveStatus = "unverified-source-field" }
quests[13611] = { id = 13611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mimiron's Sigil", description = "Mimiron's a clever one.  His entire abode is rigged with some sort of self-destruction mechanism.\n\nUnfortunately yer gonna have to race against it if ye want to get his sigil.  Check the Archivum Console for more details if ye need them.", sourceObjective = "Prospector Doren at the Ulduar Archivum wants you to obtain Mimiron's Sigil.\n\nFor more information on obtaining Mimiron's Sigil consult the Archivum Console.", progress = "Were you able to obtain the sigil, {name}?", completion = "I've got to hand it to you, {name}.  Our odds might not be the best, but I feel a lot better with you lending a hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[13612] = { id = 13612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'shan Defense", description = "Lok'tar, {race}!\n\nThe campaign is finally underway! Soon, all of Ashenvale will be in the grip of the Horde.\n\nAs we expected, our offensive is forcing the enemy to test our defenses at every position.\n\nHere at Mor'shan, their assault has been decimated! But as the vice tightens, they will have no choice but to continue to press us here.\n\nScout the region, {class}. Search for night elf survivors and cut them down before they can regroup for another assault!", sourceObjective = "Kadrak at Mor'shan Ramparts wants you to kill 5 Ashenvale Skirmishers and 5 Ashenvale Bowmen.", progress = "Was your hunt successful, {race}?", completion = "Good work, {class}!\n\nYour efforts will help keep the enemy on their heels while our forces sweep across the land!", sourceObjectiveStatus = "unverified-source-field" }
quests[13613] = { id = 13613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue the Fallen", description = "Our forces are holding up admirably, {class}.\n\nBe that as it may, there are yet wounded to attend to - many still in the field of battle.\n\nI have created a salve that should grant the wounded enough energy to return to the ramparts for treatment. Please administer it to any in need before they become lost to us.", sourceObjective = "Use the Medicated Salve on 5 Wounded Mor'shan Defenders.", completion = "Thank you, {race}. I shall include your service to the Horde in my report.\n\nI should have these troops fit to fight again in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[13614] = { id = 13614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Algalon", description = "You really did it, {name}.  Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium.\n\nYou best hurry, <lad/lass>.  Time is of the essence.", sourceObjective = "Bring the Sigils of the Watchers to the Archivum Console in Ulduar.", progress = "The console's bright lights scan the glass surface repeatedly, as if awaiting some form of input.", completion = "Stand by for verification.\n\nAccess to the Celestial Planetarium granted.  Please retrieve your key.", sourceObjectiveStatus = "unverified-source-field" }
quests[13615] = { id = 13615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empty Quivers", description = "Greetings, {class}, and welcome to the Ramparts.\n\nThings may appear a little chaotic here but do not worry. Kadrak has this juncture sealed up tight. Not a single elf has breached our lines!\n\nWhile you're here... I'm expecting a shipment of fresh supplies from Orgrimmar any day, but our watchmen are running dangerously low on arrows.\n\nBring me any you find and I will make it worth your trouble.", sourceObjective = "Truun at Mor'shan Ramparts wants you to collect 10 Serviceable Arrows from the Fallen Sky Lake region.", progress = "Have you collected the arrows we need, {class}?", completion = "Well done, {class}.\n\nThis should help get us by until our shipment arrives.", sourceObjectiveStatus = "unverified-source-field" }
quests[13616] = { id = 13616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Marshal Jacob Alerius at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13617] = { id = 13617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "West to the Strand", description = "{name}, I have a friend who could make good use of particular talents. His name is Talen and he's an archaeologist of sorts. Recently he's been fascinated with the upheaval of the old city of Zoram and its treasures.\n\nIf you're willing to lend him a hand, you can find him at the Blackfathom Camp down the path to the west.", sourceObjective = "Speak with Talen at the Blackfathom Camp in Ashenvale.", completion = "Hello, {class}.\n\nWhat's that? You say that Shyela sent you?\n\n\n\nVery well, let's get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[13618] = { id = 13618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Gorat!", description = "Gorat is one of the Horde's most adept assassins.\n\nThe mere mention of his name strikes fear into the hearts of our Alliance foes.\n\nHe is reliable, fiercely loyal, and - until now - punctual.\n\nSomething's not right, {class}.\n\nGorat's mission was to find and eliminate the elf in charge of this assault on the ramparts.\n\nHe should be somewhere in the region of Fallen Sky Lake.\n\nFind him!", sourceObjective = "Kadrak at Mor'shan Ramparts wants you to search the Fallen Sky Lake region for Gorat.", completion = "Listen carefully, {race}....", sourceObjectiveStatus = "unverified-source-field" }
quests[13619] = { id = 13619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Report", description = "<Gorat coughs deeply as he strains to speak.>\n\nIt was... an ambush....\n\nWe were... returning to the ramparts. All of us... lost....\n\nWe... discovered their leader... \n\n<Gorat painstakingly fills a vial with the blood spilling from one of his wounds.>\n\nMy men... must be avenged.... Bring this... to Kadrak....\n\nHe will know what to do....\n\n<Gorat expires.>", sourceObjective = "Gorat wants you to return the Vial of Gorat's Blood to Kadrak at Mor'shan Ramparts.", progress = "Did you find Gorat, {class}?!", completion = "<Kadrak listens intently as you share Gorat's last words.>\n\nIt is as I feared, then. May his rest be peaceful - only not yet!", sourceObjectiveStatus = "unverified-source-field" }
quests[13620] = { id = 13620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Dinah, at Once!", description = "The Horde may have never known one more loyal than Gorat. He never failed to complete a mission, and it would seem that he refuses to allow this to be his first.\n\nGorat had you deliver this vial for a purpose. Dinah is the daughter of a revered shaman, and is more powerful than she appears. Bring her the vial and hope that we are not too late.", sourceObjective = "Kadrak wants you to bring the Vial of Gorat's Blood to Dinah at Mor'shan Ramparts.", progress = "What have you there, {race}?", completion = "Let's have a look, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13621] = { id = 13621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorat's Vengeance", description = "Fortune is with us this day, {race}.\n\nGorat's blood was fresh enough for me to conduct a special ritual taught to me as a child.\n\nUse this imbued blood on Gorat's corpse to summon forth his lingering spirit.\n\nDo his final bidding, then report back here to Kadrak.\n\nSpirits keep you safe, friend.", sourceObjective = "Use Gorat's Imbued Blood on Gorat's corpse, then defeat Captain Elendilad.", completion = "Well done, {race}.\n\nThe elf captain is dead and the soul of one of our beloved brethren can sleep in peace.\n\nI shall pass on word of your deeds to my superiors in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13622] = { id = 13622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient History", description = "The pieces fit together to form an elegant hammer.  Its construction appears to be at least partially Titan in nature.\n\nThe console inside the Archivum might have some information regarding this artifact.", sourceObjective = "Bring the Shattered Fragments of Val'anyr to the Archivum Console in the Archivum in Ulduar.", progress = "Awaiting input.", completion = "Analyzing fragments... please stand by.", sourceObjectiveStatus = "unverified-source-field" }
quests[13623] = { id = 13623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery for Orendil", description = "Quickly, {name}. I will put the Bathran's Hair into this bag, but you must deliver it to my master, Orendil Broadleaf. You will find him at Maestra's Post, just south down the road on the left.\n\nBut beware, we've received reports that the post is under attack from the Horde!", sourceObjective = "Deliver the Bag of Bathran's Hair to Orendil Broadleaf at Maestra's Post in Ashenvale.", progress = "You're a brave one to come here given the circumstances.\n\nWhat business have you, stranger?", completion = "So, Evenar was succesful. Actually, more to the point, YOU were successful.\n\nI cannot thank you enough, {class}, but there is more that must be done to the leaves before they will serve as a curative for what ails the child, Relara.", sourceObjectiveStatus = "unverified-source-field" }
quests[13624] = { id = 13624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Squad of Your Own", description = "I certainly hope that you're here to help, {class}. The situation is as dire as it appears. To put it quite simply, we are losing!\n\nMy girls and I are the last line of defense against the Horde, but we're not going to get out of this one without taking the fight to them. Up for a challenge?\n\nI have a small squad of sentinels that I can loan to you. Get them close and I'm certain that their magic arrows can destroy those wreckers and invaders.\n\nSpeak to me again if you need replacements.", sourceObjective = "Use a squad of Maestra's Post Sentinels to destroy 3 Ashenvale Wreckers and slay 10 Horde Invaders.", completion = "I'd received a report about you from some of my scouts out in the forest but I had no idea how capable you are!\n\nThank you, {name}. With what you've accomplished the tide is turned. I've no doubt now that we'll rout them by the end of the day!", sourceObjectiveStatus = "unverified-source-field" }
quests[13625] = { id = 13625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning The Reins", description = "Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds.\n\nVisit the stables outside the pavilion, equip your lance, and mount up on the Quel'dorei steed. Familiarize yourself with the tactics available to you and use them to defeat the three different kinds of training dummies.", sourceObjective = "Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets and then return to Scout Shalyndria at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or the Silver Covenant Pavilion.", progress = "How goes the mounted combat practice?", completion = "Well done, {name}. Mounted combat is often hard to pick up for those accustomed to fighting on foot. I have no doubt that you'll continue to improve with practice, which is more than I can say for some warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[13626] = { id = 13626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respect for the Fallen", description = "There were two humans here: Feero Ironhand and Delgren the Purifier. They were members of a holy organization known as The Argent Dawn. Both fell defending the post when the Horde first attacked.\n\nI'm going to loan you my magical cloak. It was a gift from Cenarius that allows me to move invisibly.\n\nFind both of their corpses and retrieve Feero's hammer and Delgren's prayer book. Feero's corpse is in the courtyard and Delgren's is atop the tower.\n\nBeware, the warlock up there will be able to see you.", sourceObjective = "Retrieve Feero's Holy Hammer and The Purifier's Prayer Book.", progress = "Our losses here have been staggering.", completion = "I do not look forward to writing the letter to the Argent Dawn embassy in Darnassus. At least we'll be able to send their most prized possessions back for their loved ones.\n\nI cannot thank you enough for your courage, {name}. Please accept this on behalf of the post.", sourceObjectiveStatus = "unverified-source-field" }
quests[13627] = { id = 13627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jack Me Some Lumber", description = "Come closer. No, not too close. Don't want any unnecessary suspicion now, do we?\n\nThis coliseum requires more lumber than we've stockpiled and there's no way I'm going to pay to have it shipped in from Grizzly Hills. At the western end of Crystalsong Forest, by the Great Tree, grow a number of young Crystalsong oaks. They'd provide just the kind of planking we need for building and scaffolding. Take this axe, use it to fell the trees and then hew them into planks, but don't let anyone see you!", sourceObjective = "Bring 12 Rough Hewn Planks to Bezzle Blastbolt at the Argent Tournament Grounds.", progress = "Did you get the \"goods\" we talked about?", completion = "All excellent planks, and the price is right, too! Even better, those Argent Crusade sticks-in-the-mud will never know. They'll get their precious coliseum and I'll get my early completion bonus. Now that's a win-win if I ever saw one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13628] = { id = 13628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Got Wood?", description = "Kadrak has just received fresh orders for our troops. I hear we're to begin offensive strikes into Ashenvale!\n\nI have far too few supplies to support an assault, and my shipment from Orgrimmar has yet to arrive.\n\nI am forced to  improvise, and could use your help, {class}.\n\nSpeak with Kadrak and ask him for the reins to Brutusk. The kodo will take you to the Warsong Labor Camp. Once there, seek out Gorka and ask her to load you up with logs.", sourceObjective = "Truun wants you to ride Brutusk to the Warsong Labor Camp.\n\nSpeak with Kadrak to get Kadrak's Reins to ride Brutus.", completion = "Welcome, {class}. It is good to see that the road to Mor'shan Ramparts remains clear.", sourceObjectiveStatus = "unverified-source-field" }
quests[13629] = { id = 13629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'anyr, Hammer of Ancient Kings", description = "The Archivum Console has hinted at a possible way to rebind the fragments of Val'anyr:  you must get the fragments inside the physical form of the being known as Yogg-Saron.\n\nIt sounds like a long shot, but for an artifact of such power you think the risk might just be worth it.", sourceObjective = "Throw the Shattered Pieces of Val'anyr into Yogg-Saron's maw while he's casting Deafening Roar and defeat Yogg-Saron and recover the Reforged Hammer of Ancient Kings.\n\nThis can only be completed in Heroic mode and only if at least one Ulduar Watcher is not assisting you.", progress = "Awaiting input.", completion = "Object integrity confirmed.  Please hold while solidified residue is removed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13630] = { id = 13630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reason Why", description = "The furbolg have descended from the heights and overrun the Ruins of Ordil'Aran to the north. I believe they did so because they were attracted to what the dead cultists there uncovered:  three moonstones.\n\nLiladris Moonriver will counsel you to deal with the furbolg in a more direct manner, and I will not gainsay her, but I would ask that you go to the ruins and deactivate the moonstones.", sourceObjective = "Deactivate the Blue, Green, and Red Moonstones.", completion = "Thank you, {name}.\n\nWith the moonstones of Ordil'Aran deactivated, we should not need to worry about any further incursions of furbolg here.\n\nHowever, my scouts have returned with disturbing news from the furbolg village. There is an imminent danger massing there.\n\nI wonder, might I entice you to carry a warning to Astranaar for me?", sourceObjectiveStatus = "unverified-source-field" }
quests[13631] = { id = 13631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Is Well That Ends Well", description = "We'd best hurry now, {name}.  We're going to have to transmit the reply-code from Dalaran.\n\nTake it to Rhonin, I will meet you there.", sourceObjective = "Take the Reply-Code Alpha to Rhonin in Dalaran.", progress = "You're ready, {name}?", completion = "You're here.  Let us hope this works.  For all our sakes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13632] = { id = 13632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rear Guard Duty", description = "The moon priestess has a plan to make sure that no further furbolg descend upon us from the highlands. I am more concerned with those that are already at the ruins, some of which are massing just outside of the post.\n\nDistasteful as it may be, I must ask that you head north into the Ruins of Ordil'Aran and slay the furbolg. We cannot fight on two fronts!\n\nThank you, {class}.", sourceObjective = "Slay any 10 furbolg at the Ruins of Ordil'Aran.", progress = "Ordil'Aran was a night elf city once long ago. It fell to ruins during the Sundering and only recently had some outsiders moved in to pillage it.\n\nNow they are dead, victims of their own curiosity that attracted the furbolg down upon them.", completion = "We are in your debt, {class}. If I know anything about the furbolg, they do not like their noses bloodied.\n\nIt won't be long now before they tuck tail and return to their village.", sourceObjectiveStatus = "unverified-source-field" }
quests[13633] = { id = 13633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight of Westfall?", description = "No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end.\n\nOf course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background.\n\nHe claims to be descended from the Cooper family of Westfall. Would you visit their residence in the western part of Moonbrook in Westfall? See if you can find any proof of his story.", sourceObjective = "Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings.", progress = "Have you found anything related to the Black Knight's story?", completion = "So you're saying this knight's story is a sham? Most suspicious. Dishonorable at the least, and murderous at the worst. Still, we can't confront him until we know for certain whether he was involved in these murders.\n\nDo nothing to arouse his suspicions, {name}. Discretion will serve us well as we continue to investigate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13634] = { id = 13634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight of Silverpine?", description = "No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end.\n\nOf course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background.\n\nHe claims to hail from Valgan's Field in Silverpine Forest. It's a small farm on the western shore of Lordamere Lake. Would you visit the farm and let me know if there's any truth to his story?", sourceObjective = "Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings.", progress = "Have you found anything related to the Black Knight's story?", completion = "So you're saying this knight's story is a sham? Most suspicious. Dishonorable at the least, and murderous at the worst. Still, we can't confront him until we know for certain whether he was involved in these murders.\n\nDo nothing to arouse his suspicions, {name}. Discretion will serve us well as we continue to investigate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13635] = { id = 13635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "South Gate Status Report", description = "We're due for sending a status report over to the mountaineers in the Valley of Kings.\n\nI expect you're on your way there next anyhow - would you mind dropping it off for me? Just take the tunnel to the east, and check in at the guard station. Hand it directly to Captain Rugelfuss.", sourceObjective = "Deliver Pilot Hammerfoot's Status Report to Captain Rugelfuss in the Valley of Kings.", progress = "What brings you all the way out here?", completion = "The South Gate status report? Excellent. I've been awaiting news from them for a while.\n\nWith the increasing number of troggs in the hills on all sides, I fear the outposts will be the first to feel any aggressive action.", sourceObjectiveStatus = "unverified-source-field" }
quests[13636] = { id = 13636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpike's Orders", description = "I need to get some orders up to Mountaineer Stormpike at his post in Algaz Station. If you wouldn't mind taking them, just follow the road all the way up to the northwest and you'll be sure to see the main bunker.\n\nIf you'd like to lend a hand in accomplishing his tasks, we'd be glad to reward you for that as well.", sourceObjective = "Deliver Stormpike's Orders to Mountaineer Stormpike at Algaz Station.", completion = "Orders! Let's see what we have here... hah! He wants me to deal with the infestation of rat men. We're already in the middle of that, so no real deviation there.\n\nCare to lend a hand?", sourceObjectiveStatus = "unverified-source-field" }
quests[13637] = { id = 13637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ram Delivery", description = "The mountaineers at South Gate Outpost have requested a delivery of rams for their patrols. I didn't think we'd be able to spare any, but we can get them at least one thanks to you.\n\nMind riding it over and delivering it to Private Hammerfall for me? Just let me know when you're ready to go." }
quests[13638] = { id = 13638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Mountaineer", description = "You've proven yourself more than capable enough in a fight. I have something a bit more pressing to ask of you now.\n\nOne of my men, Mountaineer Gravelgaw, was captured by the troggs that we've been fighting in the southern mountains. Well, not so much captured as willingly gave himself up, but similar end result. I think he was hoping to identify their leader from the inside.\n\nI need you to go get him out. They'll probably be holding him near one of their upper caves deep in the mountains.", sourceObjective = "Captain Regulfuss at Thelsamar wants you to locate Mountaineer Gravelgaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[13639] = { id = 13639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resupplying the Excavation", description = "Ironband has an excavation to the southeast and he's been needing a hefty amount of explosives sent from the league for all the carving. Huldar, Miran, and Saean just departed with the most recent load and could probably use a hand.\n\nThey can't have made it very far, strong as they are. They can only move so fast laden down with those barrels.\n\nThey're taking the normal route to the site, leaving south out of town and following the curve of the Loch. Go catch up with them and help'm out, will ya?", sourceObjective = "Locate Huldar, Miran, and Saean.", completion = "Hmph, it'll take more than a Dark Iron ambush to stop the deliveries!\n\nBut Saean... I would never have suspected him to be one of their sympathizers. We've been working with him for almost a year now... maybe I missed the signs.\n\nWell, I'll consider that later.", sourceObjectiveStatus = "unverified-source-field" }
quests[13640] = { id = 13640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Management Material", description = "Truun needs wood, huh? Normally I could provide, but not today.\n\nWith constant elf attacks, gathering lumber is dangerous work. The peons I have left are reluctant to venture into the woods.\n\nYou want wood? Then you go convince the peons to work.\n\nAnd keep them safe! I cannot afford to lose any more!", sourceObjective = "Convince Demoralized Peons to work and collect 5 bundles of Freshly Cut Wood.", progress = "Did you get the wood you need?", completion = "It seems you've solved one problem only to face another, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13641] = { id = 13641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seer's Crystal", description = "Now that we know there's no truth to the Black Knight's stories, we must find a way to connect him to the murdered knights.\n\nI know a way to reveal the truth about how they died, but it requires a rare material. We must gain a seer's crystal, found only among the unbound seers who congregate near night elf ruins in the Forlorn Woods in the central part of Crystalsong Forest. Find one of these seers, {name}, and bring me the crystal it holds.", sourceObjective = "Bring a Seer's Crystal to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "Have you located a seer's crystal?", completion = "This one will do nicely. All that remains is to imbue it with the power of the Light, giving it the ability to find truth amid deception.", sourceObjectiveStatus = "unverified-source-field" }
quests[13642] = { id = 13642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bathed in Light", description = "The concoction is not quite complete; it must be bathed within the Light of Elune before we can even think about giving it to the child.\n\nThere is a known location just to the west at Lake Falathim where the goddess's moonlight always touches down, day or night. Please, {name}, I implore you for the sake of Relara, take the concoction and bathe it in Elune's radiance.\n\nBut beware, strange things have befallen the area of the lake, and I fear that it is no longer safe to go there.", sourceObjective = "Create a Bathed Concoction.", progress = "Did you have any trouble getting to the Light of Elune at Lake Falathim?", completion = "With the concoction blessed by the Light of Elune, it should be ready for delivery to Astranaar.\n\nThere is no time to waste, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13643] = { id = 13643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stories Dead Men Tell", description = "The crystal will reveal the truth about how three of the tournament's combatants died. Take it with you to the graveyard east of the Tournament Grounds and use it before the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip.\n\nIf indeed these men were murdered, then we must find a way to tie it to the Black Knight before he strikes again. Look closely at what the crystal tells you, {name}, for we must be certain these deaths were not accidental.", sourceObjective = "Use the Seer's Crystal at the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip to determine how they died, then return to Crusader Rhydalla.", progress = "Have you visisted the graves of the slain combatants?", completion = "So you say Lorien Sunblaze was done in by poison and Sir Wendell was burnt alive? Dreadful ways to die, both of them. Only Conall was killed by cold steel, and from your description, it was a coward's strike, not honorable combat that laid him in his grave.\n\nAll three sparred with and were scheduled to fight the Black Knight. This cannot be a coincidence. Now, we must find a way to prove it was the Black Knight's work.", sourceObjectiveStatus = "unverified-source-field" }
quests[13644] = { id = 13644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Which Has Risen", description = "When I sensed these... things... rising from below, I came to put them back down. I found the corpse of your friend and dragged him as far as I could before one of my fetlocks was broken. It is all that I can do to hold off these foul tendrils.\n\nThere is one that controls the tendrils and eyes. It calls itself Harbinger Aphotic -- I'm sure that you have heard it yelling from the south.\n\nThe harbinger stands out of range of my magic, but you could get to him. If you dare....", sourceObjective = "Slay Harbinger Aphotic.", progress = "The harbinger yet lives, {name}. I cannot begin to cleanse Lake Falathim until it is slain.", completion = "With the death of the harbinger, I can begin to cleanse the lake.\n\nYou have my deepest thanks, {name}. I mourn the loss of your friend, but know that his remains will fuel the reclamation of the forest hereabouts.", sourceObjectiveStatus = "unverified-source-field" }
quests[13645] = { id = 13645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Raene Wolfrunner", description = "I would ask you to deliver the gem directly to Raene Wolfrunner. Last I heard, she was still in Astranaar to the southeast.\n\nAt least the road between here and there is still relatively safe, so it should be a simple matter of following it there. Of course, if you'd rather, I believe that Sentinel Avana would be willing to loan you one of her nightsabers to swiftly make the trip.\n\nWhatever you choose, good health to you, {name}. May our paths cross again soon.", sourceObjective = "Deliver the Glowing Gem to Raene Wolfrunner at Astranaar in Ashenvale.", progress = "I am Raene Wolfrunner. Who might you be?", completion = "Teronis is dead?\n\n<The lady weeps softly for the loss of her friend and then composes herself after a moment.>\n\nWe must see to it that his sacrifice was not in vain. Are you willing to see this through, {class}?\n\nVery well, allow me some time to think about how we should proceed. I will know shortly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13646] = { id = 13646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astranaar Bound", description = "You have been of great assistance to us, {name}. Without you, we would have been wiped out by now.\n\nIt would be my pleasure to offer you one of my nightsabers anytime to ride to Astranaar up and to the southeast. I'm sure that you have very important business to attend to there.\n\nI would consider it a great kindness if you would speak with my sister, Sentinel Luara, when you arrive to tell her that I am well.\n\nJust speak to me again when you are ready to go, and anytime that you need a ride it is yours.", sourceObjective = "Speak with Sentinel Luara at Astranaar in Ashenvale.", completion = "Avana is alive?! I feared that she might be dead when we heard about the attack on Maestra's Post!\n\nAs you can see, we have our hands full with the Horde here as well.\n\nYou have given me the greatest gift by letting me know she is well. Any time that you wish to ride one of my nightsabers back to Maestra's Post, it is yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[13647] = { id = 13647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Hunt", description = "Well, you definitely have some fight in you.\n\nYou know, there are some hunter types at the lodge east of here, up in the hills - they might be right up your alley. Why don't you go pay them a visit and see if they have any work that you might be interested in?", sourceObjective = "Speak to Marek Ironheart at the Farstrider Lodge.", completion = "Hello there, laddy! The mountaineers sent you over, eh? I do suspect we might have just the sort of work you're looking for. Welcome to the Farstrider Lodge!", sourceObjectiveStatus = "unverified-source-field" }
quests[13648] = { id = 13648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Dark Iron Spy", description = "A dark iron spy has infiltrated the town, stolen documents from the Explorers' League establishment, and is now in hiding somewhere nearby. He was last sighted near the top of the hill to the south of town.\n\nA sizable reward awaits anyone who can bring this spy to justice. Dead or alive - dead preferred.", sourceObjective = "Slay Gorick Guzzledraught.", completion = "You brought that damned spy to justice! This is good news. We can all rest a little bit easier, not worrying about that one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13649] = { id = 13649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justin's Fun Test", description = "Hey there!  You look like you can handle your brew.  But can you handle your brew mug? \n\nThe Dark Irons have come back with a vengeance to ruin our celebration.  Tossing mugs at them is the best way to stop them, but first, let's see if you can toss one at old S.T.O.U.T. here.\n\nIt's easy, pick up a complimentary sampler and take a drink.  Just make sure you're facing S.T.O.U.T.  Talk to me after you've hit him 5 times.", sourceObjective = "Use the Complimentary Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Boxey Boltspinner.", sourceObjectiveStatus = "unverified-source-field" }
quests[13650] = { id = 13650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Your Hands Off The Goods!", description = "We've uncovered some incredible artifacts at this site. It's hard to be convinced that it's all authentic, but there could be serious historical potential.\n\nUnfortunately, when the troggs overran the site, we lost access to three of our most notable finds to date. I'm concerned that the troggs might have stolen them or defiled them in our absence.\n\nIf you go into the excavation, find the Upturned Giant, the Overdressed Woman, and the Broken Tablet, and make sure they're still intact.", sourceObjective = "Inspect the Upturned Giant Artifact, the Overdressed Woman Artifact, and the Broken Tablet Artifact.", progress = "Are all of our artifacts still there? Are they damaged?", completion = "Woo! I'm relieved... I was worried they'd all be destroyed by now. Thank you for checking in on them.", sourceObjectiveStatus = "unverified-source-field" }
quests[13651] = { id = 13651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Needs a Little Oil", description = "You have your wood, but the encroaching elves have made it impossible for your kodo to return to Mor'shan Ramparts.\n\nI've dispatched a runner to Splintertree to summon aid. It shouldn't take long for their forces to clear the way.\n\nIn the meantime, I would ask that you do us a service. Rust has rendered our shredders inoperable. A little lubrication and they'll be as good as new.\n\nThe oil from the rotting slimes just north of here should work just fine.", sourceObjective = "Gorka at Warsong Labor Camp wants you to collect 5 Natural Oil from the Rotting Slimes in Ashenvale.", progress = "Were you able to collect the oil we need, {class}?", completion = "Thank you for the oil, {class}. Now prepare yourself!\n\nMy runner has returned with some desperate news....\n\nSplintertree is surrounded!", sourceObjectiveStatus = "unverified-source-field" }
quests[13652] = { id = 13652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense of the Stonewrought Dam", description = "We appreciate all of your help. We'll regain control of the excavation with a little bit of time, I'm just glad to know that all of our work wasn't destroyed in the process of this occupation.\n\nWe've been greedy enough with your time. I have a friend who could really use some of your help if you have any to lend. Go to the far side of the Loch and you'll find Stonewrought Dam. Once you're there, seek out Chief Engineer Hinderweir VII.", sourceObjective = "Seek out Chief Engineer Hinderweir VII at the Stonewrought Dam.", sourceObjectiveStatus = "unverified-source-field" }
quests[13653] = { id = 13653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crisis at Splintertree", description = "There will be no help coming from Splintertree.\n\nThe elves have launched a major assault on our stronghold there and they have the place surrounded!\n\nWe must inform Kadrak or die trying!\n\nYour kodo has been loaded up with the wood you collected. Let me know when you're ready and we'll charge the enemy lines.", sourceObjective = "Gorka wants you to accompany her to Mor'shan Ramparts and report to Kadrak.\n\nSpeak to her when you are ready to depart.", progress = "What's all this about, {class}?", completion = "Gorka...\n\nWe must always be prepared for losses. Her honorable service to the Horde will not be forgotten.\n\nAnd her sacrifice shall not be in vain!", sourceObjectiveStatus = "unverified-source-field" }
quests[13654] = { id = 13654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Something About the Squire", description = "Every day, the Black Knight's squire, Maloric, makes a big show of heading to Crystalsong Forest with his axe over his shoulder. He wants us to believe he's chopping wood, but he never returns with more than a few twigs.\n\nHe usually goes toward the ruins southwest of the Mirror of Twilight. He spends a lot of time out there, even for a squire with responsibilities to his knight.\n\nFind a way to distract or incapacitate him and search him. If he's up to something, we'll know it.", sourceObjective = "Obtain a Large Femur from a Skeletal Woodcutter and use it to incapacitate Maloric. Search Maloric for evidence, then report back to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "Did the squire's behavior yield any clues?", completion = "<Crusader Rhydalla examines the bag's contents with a look of disgust on her face.>\n\nIt's all here, {name}: the poison that killed Lorien, a collection of knives, torches, and oil. No man has cause to possess these things here and no squire would do so without orders from his knightly master. We've found our murderer, {name}, but who is he working for?", sourceObjectiveStatus = "unverified-source-field" }
quests[13655] = { id = 13655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (2 of 6)", description = "The document bears the Explorers' League crest and seems to detail potential dig sites in Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Well look at that. You found one of our stolen documents!\n\nWe're much obliged for its return. Hopefully a bit of gold will suit your fancy for the finder's fee?", sourceObjectiveStatus = "unverified-source-field" }
quests[13656] = { id = 13656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (1 of 6)", description = "The document bears the Explorers' League crest and contains extensive information on the indigenous creatures of Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Hello, sonny! You seem to have found one of our stolen documents, eh?\n\nThank you kindly for bringing it back to us. We'll gladly lend some coin as thanks for its return.", sourceObjectiveStatus = "unverified-source-field" }
quests[13657] = { id = 13657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (3 of 6)", description = "The document bears the Explorers' League crest and contains historical records for all the notable locations in Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Our historical records! The thought of Dark Iron vermin delving into our past just made me sick to my stomach.\n\nWe appreciate you bringing this back to us. We'd like to offer you some coin as a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[13658] = { id = 13658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (4 of 6)", description = "The document bears the Explorers' League crest and seems to detail transport routes utilized by the league into and out of Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Ug, I can't believe they got their hands on our transport routes - that was just asking for trouble!!\n\nThank you for getting this back to us before they were able to do much with it! You probably saved us a lot of heartache. Please accept some coin as a reward for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[13659] = { id = 13659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (6 of 6)", description = "The document bears the Explorers' League crest and contains detailed assessments of the various threats present within Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Hah! Think they got a kick out of seeing how low they were on our list of threat assessments? This document was admittedly a bit out of date, but none the less amusing.\n\nOf course, we'll offer you some money as a reward for returning this anyway - your efforts are appreciated!", sourceObjectiveStatus = "unverified-source-field" }
quests[13660] = { id = 13660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (5 of 6)", description = "The document bears the Explorers' League crest and contains a detailed list of the artifacts excavated by Ironband's workers in southeastern Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Our artifact records! I was pretty well worried what the Dark Irons might try to steal with this information at their disposal.\n\nThank you for bringing this back to us. We'll gladly part with some coin to express our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[13661] = { id = 13661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heartfelt Appreciation", description = "You located all of our documents! We can't think you enough for the help... we'd all but given up hope that the dark irons would be able to act upon all of this information soon. It's good to know that they'll be left blind in their attacks for quite a while yet.\n\nTo thank you for all of your efforts on our behalf, we would like to offer you a gift. An artifact really... something we recovered from one of our digs. You have the appreciation of all of the Explorers' League.You will be able to choose one of these rewards:", sourceObjective = "You located all of our documents! We can't thank you enough for the help... we'd all but given up hope. It seemed sure that the Dark Irons would be able to act upon all of this information soon. It's good to know that they'll be left blind in their attacks for quite a while yet.\n\nTo thank you for all of your efforts on our behalf, we would like to offer you a gift. An artifact really... something we recovered from one of our digs. You have the appreciation of all of the Explorers' League.", sourceObjectiveStatus = "unverified-source-field" }
quests[13662] = { id = 13662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining Acceptance", progress = "You've worked your way up through the Brotherhood's corporate hierarchy, {race}. We have begun to look favorably upon you. Quite an accomplishment!\n\nIf you're interested in more work and earning more respect amongst us, listen up.\n\nWe can refine the fiery flux by adding a simple Dark Iron residue to the mix. The Dark Iron residue can be found in Blackrock Depths.\n\nBring me all the Dark Iron residue you find!", completion = "Keep the residue pouring in!" }
quests[13663] = { id = 13663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight's Orders", description = "We must discover who sent the Black Knight to the tournament and what his master hopes to gain by killing the competitors.\n\nThe Kirin Tor has offered to help in this matter and provided us with something to help our search.\n\nTake this enchanted bridle to the Black Knight's camp on the eastern edge of the tournament grounds and use it to gain control over the Black Knight's gryphon. The bridle's magic will force the gryphon to take you to his master's home. Search it and return with anything you find.", sourceObjective = "Use the Enchanted Bridle to gain control of the Black Knight's Gryphon and ride it to its destination. Once you have arrived, recover the Stolen Tournament Invitation and the Black Knight's Orders and bring them to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "What did you discover?", completion = "<Crusader Rhydalla's face pales as she reads the orders.>\n\nThis can only mean one thing, {name}. The Black Knight is a member of the Cult of the Damned and has been sent by Arthas to disrupt the tournament!\n\nThe Black Knight has proven himself a fearsome combatant, and you will need to be every bit as good if you wish to face him. When you are a champion, return to me and we'll find a way to ensure his defeat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13664] = { id = 13664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight's Fall", description = "We must put an end to the Black Knight's scheming, and show those who oppose us that we will not stand by and allow our champions to be murdered.\n\nBy now, he will suspect that someone is on his trail. Challenge him in the light of day, where he cannot refuse or murder in the dark, {name}.\n\nUse my argent charger for the battle. It's housed in the stables.\n\nSpeak to Squire Cavin at the Ring of Champions. The squire will call the Black Knight to battle, but you will make him answer for his crimes.", sourceObjective = "Defeat the Black Knight and then speak to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "Is it done?", completion = "With the death of the Black Knight, the tournament may once again serve its purpose. The champions of the Horde and Alliance may demonstrate their skill at arms and train for the day when Arthas and his minions will no longer threaten us.\n\nYou have the thanks of the Argent Crusade, {name}, and that of all who have answered our call.", sourceObjectiveStatus = "unverified-source-field" }
quests[13665] = { id = 13665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of Stormwind adore their knights and are looking forward to seeing us win the melee. To that end, they've been honing their skills against the other valiants.\n\nI suggest you do the same.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Elwynn steed, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Captain Joseph Holley at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make Stormwind proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13666] = { id = 13666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Arcanist Taelis at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So there is some truth to those old tales? It seems they did not lie about the quality of the blade. Well done, {name}. The champion who wields it will be a lucky man, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13667] = { id = 13667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Argent Tournament", description = "We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy.\n\nArcanist Taelis is the Silver Covenant's representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Alliance tent in the northeastern part of the grounds.", sourceObjective = "Speak with Arcanist Taelis at the Argent Tournament grounds to enroll in the tournament.", completion = "I have entered your name in the rolls, {name}. As an aspirant you will train with others who wish to compete in the tournament and hone your mounted combat skills. Once you have proven yourself, you will be allowed to enter the lowest rank of competition on behalf of your capital city.", sourceObjectiveStatus = "unverified-source-field" }
quests[13668] = { id = 13668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Argent Tournament", description = "We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy.\n\nMagister Edien Sunhollow is the Sunreaver representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Horde tent in the southeastern part of the grounds.", sourceObjective = "Speak with Magister Edien Sunhollow at the Argent Tournament grounds to enroll in the tournament.", completion = "I have entered your name in the rolls, {name}. As an aspirant you will train with others who wish to compete in the tournament and hone your mounted combat skills. Once you have proven yourself, you will be allowed to enter the lowest rank of competition on behalf of your capital city.", sourceObjectiveStatus = "unverified-source-field" }
quests[13669] = { id = 13669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Our champions have taken a liking to ancient weapons produced here in Northrend.\n\nI've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Arcanist Taelis at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "There's no doubt that this is a blade of exquisite quality and balance. Now I understand why these weapons are so coveted among the champions of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13670] = { id = 13670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "The Ironforge grand champion's squire told me an intriguing story.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Arcanist Taelis at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the squire said it would be, but where did he find out about it? No matter; it will serve its new owner well. Perhaps it's only fair that Ironforge's grand champion be the one to wield it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13671] = { id = 13671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training In The Field", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament.\n\nTravel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.", sourceObjective = "Avareth Swiftstrike at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment.", progress = "Have you tested yourself in combat against the Scourge?", completion = "You have shown yourself a capable combatant, {name} and you will serve as an example to the rest of the aspirants who clamor to compete on behalf of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13672] = { id = 13672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up To The Challenge", description = "When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant.\n\nWhen you are ready to begin the challenge, return to me.", sourceObjective = "Present Arcanist Taelis at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge.", progress = "Do you wish to take the aspirant's challenge?", completion = "Very well, I will make the arrangements.", sourceObjectiveStatus = "unverified-source-field" }
quests[13673] = { id = 13673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Magister Edien Sunhollow at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So there is some truth to those old tales? It seems they did not lie about the quality of the blade. Well done, {name}. The champion who wields it will be a lucky man, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13674] = { id = 13674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Our champions have taken a liking to ancient weapons produced here in Northrend.\n\nI've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Magister Edien Sunhollow at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "There's no doubt that this is a blade of exquisite quality and balance. Now I understand why these weapons are so coveted among the champions of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13675] = { id = 13675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "I heard an interesting story from one of the Ogrimmar valiants.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Magister Edien Sunhollow at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the valiant said it would be, but where did he find out about it? No matter; it will serve its new owner well. Perhaps it's only fair that Orgrimmar's grand champion be the one to wield it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13676] = { id = 13676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training In The Field", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament.\n\nTravel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.", sourceObjective = "Amariel Sunsworn at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment.", progress = "Have you tested yourself in combat against the Scourge?", completion = "You have shown yourself a capable combatant, {name} and you will serve as an example to the rest of the aspirants who clamor to compete on behalf of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13677] = { id = 13677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning The Reins", description = "Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds.\n\nVisit the stables outside the pavilion, equip your lance, and mount up on the Sunreaver hawkstrider. Familiarize yourself with the mount and use its abilities to defeat the three different kinds of training dummies.", sourceObjective = "Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets, and then return to Galathia Brightdawn at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or the Sunreaver Pavilion.", progress = "How goes the mounted combat practice?", completion = "Well done, {name}. Mounted combat is often hard to pick up for those accustomed to fighting on foot. I have no doubt that you'll continue to improve with practice, which is more than I can say for some warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[13678] = { id = 13678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up To The Challenge", description = "When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant.\n\nWhen you are ready to begin the challenge, return to me.", sourceObjective = "Present Magister Edien Sunhollow at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge.", progress = "Do you wish to take the aspirant's challenge?", completion = "Very well, I will make the arrangements.", sourceObjectiveStatus = "unverified-source-field" }
quests[13679] = { id = 13679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aspirant's Challenge", description = "You have trained hard as an aspirant, {name}, and now the time has come to test your mounted combat skills against a skilled opponent.\n\nEquip your lance, then go to the stables outside the pavilion and mount up on the stabled Quel'dorei steed.\n\nAt the Aspirants' Ring on the northern side of the tournament grounds, you'll find Squire David. He'll make certain that you're ready for the fight and call out your opponent.\n\nGood luck, {name}. May your horse be steady and your aim true.", sourceObjective = "Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Arcanist Taelis at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you faced your challenge?", completion = "Congratulations are in order, {name}. You have bested your challenger and earned the right to advance to the rank of valiant.", sourceObjectiveStatus = "unverified-source-field" }
quests[13680] = { id = 13680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aspirant's Challenge", description = "You have trained hard as an aspirant, {name}, and now the time has come to test your mounted combat skills against an experienced opponent.\n\nEquip your lance, then go to the stables outside the pavilion and mount the Sunreaver hawkstrider.\n\nAt the Aspirants' Ring on the northern side of the tournament grounds, you'll find a human child called Squire David. He'll ask if you're ready for the fight and call out your opponent.\n\nGood luck, {name}. May your mount be steady and your aim true.", sourceObjective = "Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Magister Edien Sunhollow at the Argent Tournament Grounds.", progress = "Have you faced your challenge?", completion = "Congratulations are in order, {name}. You have bested your challenger and earned the right to advance to the rank of valiant.", sourceObjectiveStatus = "unverified-source-field" }
quests[13681] = { id = 13681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Chip Off the Ulduar Block", description = "Getting stone for this job has been a nightmare, I tell ya! There are tons of stone available from ruins in safe places, but those holier-than-thou paladins won't go for it. Something about 'priceless artifacts.'\n\nAnyway, whining about that isn't going to get this place built. There are tons of crumbling titan ruins in the Foot Steppes and at the Inventor's Library in Storm Peaks. Take my, uh, 'chisel' with you and see if you can break those huge blocks into useful pieces.", sourceObjective = "Bring 15 Small Stone Blocks to Bozzle Blastbolt at the Argent Tournament Grounds.", progress = "Did you get that stone?", completion = "These should do. Just don't go around blabbing to those crusaders about where you got them from. I'm sure they'll get upset. But, hey, it's not like the titans have come back for them. They're fair game, I say. Good work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13682] = { id = 13682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat From Above", description = "Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated.\n\nOur skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", sourceObjective = "Eadric the Pure at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.", completion = "{name}, you and your allies have spared the tournament from a devastating attack. Though our skytalon riders are brave, they  have their hands full keeping the peace on the tournament grounds and would be hard-pressed to defend the skies against the cult's attack. You have the thanks of the Argent Crusade and all who have gathered here to compete.", sourceObjectiveStatus = "unverified-source-field" }
quests[13683] = { id = 13683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping the Rituals", description = "I could not help but overhear Illiyana's loss. I understand her need for revenge. I am wondering if while you are exacting it, you could do us a service?\n\nNo doubt you have already seen the satyr of Satyrnaar and Xavian conducting vile rituals. I believe that they are preparing their rituals to corrupt any of the night elves they capture, turning them into satyrs. We draenei also have problems with fel magic exposure.\n\nWould you disturb their ritual gems while you are there?", sourceObjective = "Disturb 8 Ritual Gems.", progress = "Please see to it that you disturb as many of the ritual gems as you can.\n\nThe last thing that we want is for any of the draenei here to be twisted into one of the Broken, or the elves to be corrupted into more satyrs.", completion = "We are in your debt, {class}.\n\nUnable to complete their nefarious rituals, the satyr are now fighting a losing battle where they are unable to replenish their numbers.", sourceObjectiveStatus = "unverified-source-field" }
quests[13684] = { id = 13684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Stormwind", description = "You've proven yourself worthy of competing under the banner of Stormwind, {name}. Now, you should introduce yourself to Marshal Jacob Alerius, who leads the Stormwind delegation. As Stormwind's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Marshal Jacob Alerius at the Argent Tournament Grounds to become a valiant of Stormwind.", completion = "Welcome aboard then, Valiant {name}. The Stormwind delegation is proud to count you among its members.", sourceObjectiveStatus = "unverified-source-field" }
quests[13685] = { id = 13685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Ironforge", description = "You've proven yourself worthy of competing under the banner of Ironforge, {name}. Now, you should introduce yourself to Lana Stouthammer, who leads the Ironforge delegation. As Ironforge's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Lana Stouthammer at the Argent Tournament Grounds to become a valiant of Ironforge.", completion = "It's good to meet you, valiant. Ironforge needs competitors like you to prevail in the tournament.", sourceObjectiveStatus = "unverified-source-field" }
quests[13688] = { id = 13688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Gnomeregan", description = "You've proven yourself worthy of competing under the banner of Gnomeregan, {name}. Now, you should introduce yourself to Ambrose Boltspark, who leads the Gnomeregan delegation. As the gnomish grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Ambrose Boltspark at the Argent Tournament Grounds to become a valiant of Gnomeregan.", completion = "Welcome aboard then, Valiant {name}. The Gnomeregan delegation is proud to count you among its members.", sourceObjectiveStatus = "unverified-source-field" }
quests[13689] = { id = 13689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Darnassus", description = "You've proven yourself worthy of competing under the banner of Darnassus, {name}. Now, you should introduce yourself to Jaelyne Evensong, who leads the Darnassus delegation. As the night elf grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Jaelyne Evensong at the Argent Tournament Grounds to become a valiant of Darnassus.", completion = "Welcome to the Darnassus tournament delegation, {name}. It will be a pleasure to train and compete alongside you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13690] = { id = 13690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of The Exodar", description = "You've proven yourself worthy of competing under the banner of the Exodar, {name}. Now, you should introduce yourself to Colosos, who leads the Exodar delegation. As the draenei grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Colosos at the Argent Tournament Grounds to become a valiant of the Exodar.", completion = "Welcome aboard then, Valiant {name}. The Exodar's delegation is proud to count you among its members.", sourceObjectiveStatus = "unverified-source-field" }
quests[13691] = { id = 13691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Orgrimmar", description = "You've proven yourself worthy of competing under the banner of Orgrimmar, {name}. Now, you should speak with Mokra the Skullcrusher, who leads Orgrimmar's competitors. As Orgrimmar's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Mokra the Skullcrusher at the Argent Tournament Grounds to become a valiant of Orgrimmar.", completion = "So you want to compete for Orgrimmar? Just because you've beaten up a few dummies doesn't mean you'll win, but you'll be training with the best from now on.", sourceObjectiveStatus = "unverified-source-field" }
quests[13692] = { id = 13692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sword and the Sea", description = "My sword was lost at sea.  Catch it and bring it back!", sourceObjective = "Old Man Barlo in Crystalsong Forest wants you to bring him the Sword of Knighthood.", sourceObjectiveStatus = "unverified-source-field" }
quests[13693] = { id = 13693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Sen'jin", description = "You've proven yourself worthy of competing under the banner of Sen'jin, {name}. Now, you should speak with Zul'tore who leads Sen'jin's warriors. As the troll grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Zul'tore at the Argent Tournament Grounds to become a valiant of Sen'jin.", completion = "You think you have what it takes to compete for Sen'jin? I think we'll be finding out.", sourceObjectiveStatus = "unverified-source-field" }
quests[13694] = { id = 13694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Thunder Bluff", description = "You've proven yourself worthy of competing under the banner of Thunder Bluff, {name}. Now, you should speak with Runok Wildmane, who leads Thunder Bluff's competitors. As Thunder Bluff's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Runok Wildmane at the Argent Tournament Grounds to become a valiant of Thunder Bluff.", completion = "On behalf of Thunder Bluff and its warriors, I welcome you, {name}. Always fight honorably and bravely beneath our banner.", sourceObjectiveStatus = "unverified-source-field" }
quests[13695] = { id = 13695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Undercity", description = "You've proven yourself worthy of competing under the banner of the Undercity, {name}. Now, you should speak with Deathstalker Visceri, who leads the Undercity delegation. As grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Deathstalker Visceri at the Argent Tournament Grounds to become a valiant of the Undercity.", completion = "Welcome to the Undercity delegation. {name}. As a valiant, you'll train with us to prepare you for the highest level of competition.", sourceObjectiveStatus = "unverified-source-field" }
quests[13696] = { id = 13696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Silvermoon", description = "You've proven yourself worthy of competing under the banner of Silvermoon, {name}. Now, you should speak with Eressea Dawnsinger, who leads the Silvermoon delegation. As Silvermoon's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Eressea Dawnsinger at the Argent Tournament Grounds to become a valiant of Silvermoon.", completion = "So you want to compete for Silvermoon? Very well. I'll add you to the rolls and you may begin working with the other valiants immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13697] = { id = 13697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Mokra the Skullcrusher at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13698] = { id = 13698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosives Shredding", description = "I hate to send you back in there, but based on your description of what's going on, we can't let them use all of those explosives they have stored up!\n\nIt's too dangerous for you to try to destroy them yourself, but if you were to steal one of their shredders, I'm sure they're tough enough to withstand the explosions.\n\nAfter you've destroyed their explosives, return here with the shredder. There's no sense in letting them have it back.", sourceObjective = "Use a Warsong Shredder to destroy 8 Kegs of Explosives.", progress = "Time's running out, {name}.", completion = "I saw those explosions all of the way from over here! Those filthy orcs and their goblin lackeys are going to have a hard time doing anything to despoil the forest now!\n\nWe can't thank you enough, {name}. Will this do?", sourceObjectiveStatus = "unverified-source-field" }
quests[13699] = { id = 13699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Stormwind in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Marshal Jacob Alerius at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level on behalf of Stormwind, riding in the grand melee with your weapon at the ready and our mighty pennant at your back.", sourceObjectiveStatus = "unverified-source-field" }
quests[13702] = { id = 13702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Alliance city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13703] = { id = 13703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Ironforge", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Ironforge's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Ironforge, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Lana Stouthammer again if you wish to become a valiant of Ironforge.", completion = "We are proud that you have decided to join us and I know you will shine on the field.", sourceObjectiveStatus = "unverified-source-field" }
quests[13704] = { id = 13704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Gnomeregan", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Gnomeregan's delegation could really benefit from a {class} like you.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Gnomeregan, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Ambrose Boltspark again if you wish to become a valiant of Gnomeregan.", completion = "We're proud to count you among us, {name}, and we look forward to training with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13705] = { id = 13705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of The Exodar", description = "Welcome, champion. Word of your deeds has already reached my ears. Do you wish to join the Exodar's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of the Exodar, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Colosos again if you wish to become a valiant of the Exodar.", completion = "It's good to have you on our team, {name}. We will all benefit from training with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13706] = { id = 13706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Darnassus", description = "Welcome, champion. I have heard of your accomplishments and we would be honored if you would join the delegation from Darnassus.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Darnassus, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Jaelyne Eveonsong again if you wish to become a valiant of Darnassus.", completion = "The warriors of Darnassus are honored to fight and train beside you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13707] = { id = 13707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Orgrimmar", description = "So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Orgrimmar's delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Orgrimmar, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Mokra the Skullcrusher again if you wish to become a valiant of Orgrimmar.", completion = "Welcome, then, {name}. I look forward to watching you train with my men.", sourceObjectiveStatus = "unverified-source-field" }
quests[13708] = { id = 13708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Sen'jin", description = "Greetings, champion. If you are willing, I would welcome you into Sen'jin's tournament delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Sen'jin, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Zul'tore again if you wish to become a valiant of Sen'jin.", completion = "I am glad that you have decided to join us and look forward to seeing you in action.", sourceObjectiveStatus = "unverified-source-field" }
quests[13709] = { id = 13709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Thunder Bluff", description = "Welcome, champion. As grand champion of the Thunder Bluff delegation, I would be honored to welcome you into our ranks, if you are willing.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Thunder Bluff, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Runok Wildmane again if you wish to become a valiant of Thunder Bluff.", completion = "I am honored that you have chosen to join our delegation. I know you will make us proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13710] = { id = 13710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Undercity", description = "Welcome, champion. The Forsaken delegation could always use more {class}s like you. Would you join us?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of the Undecity, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Deathstalker Visceri again if you wish to become a valiant of the Undercity.", completion = "You have chosen wisely, {name}. Both of us will benefit from this arrangement.", sourceObjectiveStatus = "unverified-source-field" }
quests[13711] = { id = 13711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Silvermoon", description = "So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Silvermoon's delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Silvermoon, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Eressea Dawnsinger again if you wish to become a valiant of Silvermoon.", completion = "It will be an honor training and competing with you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13712] = { id = 13712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Rescue!", description = "You're coming with me, {name}.\n\nThere's no one else that I can spare, and we cannot afford for Splintertree to be lost.\n\nPrepare yourself, and speak to me again when you are ready.", sourceObjective = "Speak to Kadrak at Mor'shan Ramparts and accompany him to Splintertree Post.", progress = "Work complete!", completion = "Gorka's death was not in vain, {name}.\n\nSplintertree would have certainly fallen if we hadn't come when we did.\n\nNow we must get to work shoring up her defenses.\n\nThis isn't over....", sourceObjectiveStatus = "unverified-source-field" }
quests[13713] = { id = 13713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Ironforge in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Lana Stouthammer at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level on behalf of Ironforge, riding in the grand melee with your weapon at the ready and our mighty pennant at your back.", sourceObjectiveStatus = "unverified-source-field" }
quests[13714] = { id = 13714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Lana Stouthammer at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13715] = { id = 13715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Ambrose Boltspark at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13716] = { id = 13716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Colosos at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13717] = { id = 13717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Jaelyne Evensong at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13718] = { id = 13718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Marshal Jacob Alerius at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13719] = { id = 13719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Zul'tore at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13720] = { id = 13720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Runok Wildmane at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13721] = { id = 13721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Deathstalker Visceri at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13722] = { id = 13722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Eressea Dawnsinger at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13723] = { id = 13723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Gnomeregan in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Ambrose Boltspark at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level on behalf of Gnomeregan, riding in the grand melee with your weapon at the ready and our mighty pennant at your back.", sourceObjectiveStatus = "unverified-source-field" }
quests[13724] = { id = 13724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of the Exodar in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Colosos at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level on behalf of the Exodar, riding in the grand melee with your weapon at the ready and our mighty pennant at your back.", sourceObjectiveStatus = "unverified-source-field" }
quests[13725] = { id = 13725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Darnassus in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Jaelyne Evensong at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level on behalf of Darnassus, riding in the grand melee with your weapon at the ready and our mighty pennant at your back.", sourceObjectiveStatus = "unverified-source-field" }
quests[13726] = { id = 13726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Mokra the Skullcrusher at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level, riding in the grand melee and crushing the competition under the banner of Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13727] = { id = 13727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Zul'tore at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level, riding in the grand melee and crushing the competition under the banner of the Darkspears.", sourceObjectiveStatus = "unverified-source-field" }
quests[13728] = { id = 13728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Runok Wildmane at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level, riding in the grand melee and crushing the competition under the banner of the Thunder Bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[13729] = { id = 13729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Deathstalker Visceri at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level, riding in the grand melee and crushing the competition under the banner of the Undercity.", sourceObjectiveStatus = "unverified-source-field" }
quests[13730] = { id = 13730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing With Felfire", description = "<Draaka leans down to speak to you.>\n\nListen... Before you say anything, I KNOW we're not to meddle with demonic energies....\n\nBut look around you! These are desperate times, {class}.\n\nWe'll most likely die here, regardless. May as well go out in a blaze of glory, I say!\n\nSo... Are you in?\n\nTake this canister and go southeast to Felfire Hill. Use it near the patches of felfire and bring it back to me when you've filled it.\n\nOh, and best not to mention this to anyone....", sourceObjective = "Draaka in Splintertree wants you to fill the Reinforced Canister with 7 Felfires from Felfire Hill.", completion = "Oh, yes!\n\nThis will teach those elves, just you watch!", sourceObjectiveStatus = "unverified-source-field" }
quests[13731] = { id = 13731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Eressea Dawnsinger at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level, riding in the grand melee and crushing the competition under the banner of Silvermoon.", sourceObjectiveStatus = "unverified-source-field" }
quests[13732] = { id = 13732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Alliance city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13733] = { id = 13733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Alliance city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13734] = { id = 13734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Alliance city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13735] = { id = 13735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Alliance city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13736] = { id = 13736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of Orgrimmar!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Horde city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13737] = { id = 13737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of the Darkspear!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Horde city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13738] = { id = 13738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of the Thunder Bluff!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Horde city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13739] = { id = 13739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of the Forsaken!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Horde city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13740] = { id = 13740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of Silvermoon!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Horde city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13741] = { id = 13741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Lana Stouthammer at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13742] = { id = 13742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Lana Stouthammer at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "<The grand champion accepts the Blade of Drak'Mar from you.>\n\nA fine weapon, and perfectly balanced. It will serve me well in the next match.", sourceObjectiveStatus = "unverified-source-field" }
quests[13743] = { id = 13743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Lana Stouthammer at the Argent Tournament Grounds wants you to bring her Winter's Edge.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13744] = { id = 13744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Rollo Sureshot at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "Welcome back from your exercises, {name}. Even while we practice for the competition, it's good to remind ourselves that the Scourge is still out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[13745] = { id = 13745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of Ironforge are looking forward to hearing of our success. To that end, they've been honing their skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same. The valiants practice in the ring just outside our tent. Equip your lance, go to the stables outside the pavilion and mount the stabled Ironforge ram, then challenge other Alliance valiants.", sourceObjective = "Bring 3 Marks of the Valiant to Clara Tumblebrew at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make Ironforge proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13746] = { id = 13746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Ambrose Boltspark at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13747] = { id = 13747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Ambrose Boltspark at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "<Ambrose accepts the Blade of Drak'Mar from you.>\n\nA fine weapon, and perfectly balanced. It will serve me well in the next match.", sourceObjectiveStatus = "unverified-source-field" }
quests[13748] = { id = 13748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "That's the last time I ever spar with a death knight.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Ambrose Boltspark at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13749] = { id = 13749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Tickin Gearspanner at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "Welcome back from your exercises, {name}. I'm confident that you will make us proud when the competition starts.", sourceObjectiveStatus = "unverified-source-field" }
quests[13750] = { id = 13750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. We know everyone's looking forward to seeing us in the competition. To that end, we've been honing our skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled turbostrider, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Flickin Gearspanner at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make us proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13751] = { id = 13751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tell No One!", description = "Perfect!\n\nThis will show the elves what the Horde is capable of when we're backed into a corner.\n\nListen, {name}. You must say nothing of this to anyone!\n\nGarrosh will surely approve once he sees the results, but if we are found out beforehand, our heads will be placed on spikes!\n\n<Draaka hands you a hastily written note.>\n\nBring this to Durak. You can find him in the mines behind me, just to the north. He will instruct you further.", sourceObjective = "Draaka in Splintertree wants you to bring the Hastily Written Note to Durak.\n\nProvided item:", completion = "What's this? Who are you!?\n\n<Durak reads Draaka's note.>\n\nHrmphh...\n\nDraaka should know better than to be so brazen, but it looks like you're up to your eyes in this with as much to lose as anyone.\n\nVery well.", sourceObjectiveStatus = "unverified-source-field" }
quests[13752] = { id = 13752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Colosos at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
