quests[13777] = { id = 13777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Mulgore kodo, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Anka Clawhoof at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Training against the other valiants will sharpen your claws and hone your battle insticts. When the competition begins, you will be ready.", sourceObjectiveStatus = "unverified-source-field" }
