quests[13782] = { id = 13782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat. \n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Forsaken warhorse, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Handler Dretch at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Training against the other valiants will sharpen your claws and hone your battle insticts. When the competition begins, you will be ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[13783] = { id = 13783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Eressea Dawnsinger at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with.", sourceObjectiveStatus = "unverified-source-field" }
quests[13784] = { id = 13784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Eressea Dawnsinger at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "This is a fine weapon that will help me crush the competition. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13785] = { id = 13785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Eressea Dawnsinger at the Argent Tournament Grounds wants you to bring her Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13786] = { id = 13786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Kethiel Sunlance at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "A good day of training will never hurt anyone. It's good to see you keeping up.", sourceObjectiveStatus = "unverified-source-field" }
quests[13787] = { id = 13787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Silvermoon hawkstrider, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Aneera Thuron at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Training against the other valiants will sharpen your claws and hone your battle insticts. When the competition begins, you will be ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[13788] = { id = 13788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat From Above", description = "The Argent Crusade has doubled the guard since your exposure of the Cult of the Damned's infiltrator. They know the cultists won't stop until they've destroyed this area and thwarted the tournament.\n\nThe Argent Crusade's scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party.\n\nYou must intercept and destroy them before they attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", sourceObjective = "Crok Scourgebane at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.", completion = "{name}, you have spared the tournament from a devastating attack. The Argent Crusade and all who gather here are in our debt and we'll make certain they remember it. For all their bluster about providing protection, the peacekeepers and skytalons spend more time breaking up drunken brawls than keeping us safe from the Scourge.\n\nIt's no matter. We always protect our own.", sourceObjectiveStatus = "unverified-source-field" }
quests[13789] = { id = 13789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Battle To The Enemy", description = "The coliseum is perched in the most dangerous part of the world, {name}. The territory we've taken from the Scourge has been paid for in blood and misery, yet the enemy continues to strike back with a seemingly limitless army. To make matters worse, this undead army is supported and assisted by mortal sympathizers, the Cult of the Damned.\n\nGo forth into Icecrown and slay any cultists you encounter.", sourceObjective = "Cellian Daybreak at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill Cult of the Damned members in any part of Icecrown.", progress = "Have you tested yourself in combat?", completion = "You are a true champion, {name}, both inside the ring and on the field. We must all be vigilant against the Scourge and you are a great example to our brethren and your own people.", sourceObjectiveStatus = "unverified-source-field" }
quests[13790] = { id = 13790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, besting challengers of all levels. When the tournament begins, those you have defeated will have redoubled their efforts and will seek to avenge their losses to you.\n\nIt would be wise to continue practicing your skills against the combatants waiting in the Ring of Champions. Equip your lance, go to the stables on the southern side of the grounds. then mount up on any mount you're permitted to use, and face the champions.", sourceObjective = "Bring 4 Marks of the Champion to Luuri at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you finished training with the other champions?", completion = "Well done. Training against the other champions is one of the best ways to prepare yourself for tournament competition. I know you'll make the Alliance proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13791] = { id = 13791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Battle To The Enemy", description = "While we all play at mock combat, it will do us good to remember that the real enemy surrounds us. The Argent Crusade wants to use competition to find the best fighters, but we can tell that by who returns from battle. Let's show the paladins that we are willing to take battle to the Cult of the Damned, even while making preparations for the tournament.\n\nGo forth into Icecrown and slay any of the cultists you encounter. They have a strong presence around Aldur'thar and Deathspeaker's Watch.", sourceObjective = "Zor'be the Bloodletter at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.", progress = "Have you tested yourself in combat?", completion = "You have done well in demonstrating our commitment to fighting the Scourge, no matter where we are or what we are doing.", sourceObjectiveStatus = "unverified-source-field" }
quests[13792] = { id = 13792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadewalker", description = "Now that the demon gates have been destroyed, the power of the forest must be replenished. The Forest Heart must be retrieved!\n\nGaivan Shadewalker, a powerful druid of the claw, has gone southwest, past Felfire Hill, to the Dor'Danil Barrow Den. Therein rests the Forest Heart. It is protected by the druids of Ashenvale deep below the ground.\n\nSeek out Gaivan and tell him of what has transpired, {name}.", sourceObjective = "Speak with Gaivan Shadewalker pacing outside the entrance to the Dor'Danil Barrow Den in Ashenvale.", completion = "You are brave to come here, {class}, but you may be too late. All of the druids are either dead or have been driven insane.\n\nStill, your tale is intriguing, and if what you say is true, then Gnarl must have the Forest Heart and soon, or Ashenvale will begin to wither!", sourceObjectiveStatus = "unverified-source-field" }
quests[13793] = { id = 13793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, overcoming challengers of all levels. You must make certain that you can defeat anyone you face when the tournament begins.\n\nYou should continue honing your own skills and learning more about the weaknesses of your opponents. Champions representing all cities practice in the Ring of Champions near the stables. Go to the stables, equip your lance, and pick any mount you're permitted to ride, then face the champions.", sourceObjective = "Bring 4 Marks of the Champion to Illyrie Nightfall at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you finished training with the other champions?", completion = "You handle your mount well, {name}. In time, your competitors will learn to fear you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13794] = { id = 13794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eadric the Pure", description = "I have asked my brothers of the Argent Crusade to work closely with those who rise to the rank of champion. Eadric the Pure, our brotherhood's grand champion, helps oversee training exercises for champions from all cities and helps them make their final preparations for tournament competition.\n\nPlease go and introduce yourself to him. I know he'll be eager to meet you and work with you on your way to competing against Azeroth's greatest champions.", sourceObjective = "Speak with Eadric the Pure at the Argent Tournament Grounds.", completion = "It's good to finally meet you, champion. The highlord has asked me to help coordinate the efforts of all champions to train together and bolster the defenses of the tournament grounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[13795] = { id = 13795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scourgebane", description = "The leader of the Knights of the Ebon Blade delegation has asked to speak you, {class}. Crok Scourgebane is as fearsome a combatant as they come and I have no doubt he'll have much to ask of you.\n\nThe Knights of the Ebon Blade have made camp on the north side of the tournament grounds, west of the tent housing the Alliance delegations.", sourceObjective = "Speak with Crok Scourgebane at the Argent Tournament Grounds.", completion = "So you have become a champion, {name}. I had no doubt that it would happen. We knights have been trained in the heat of battle, not in front of wooden dummies. Let's show the paladins and their guests what battle has made us.", sourceObjectiveStatus = "unverified-source-field" }
quests[13796] = { id = 13796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forest Heart", description = "You must get the Forest Heart to Gnarl at all costs!\n\nDown at the bottom of the Dor'Danil Barrow Den it sits, corrupted by the Horde. Only Gnarl can cleanse it.\n\nIn order to move it, though, you'll need a Power of Nature. If you collect enough untainted spirits from the Severed druids and keepers, the spirits can be combined into a Power of Nature.\n\nGood luck, {name}!", sourceObjective = "Obtain the Forest Heart.", progress = "{name}, you have returned.", completion = "The Forest Heart! It's corrupted!\n\n<The great ancient creaks as its immense limbs begin to perform a ritual.>\n\nStand back, {name}, I will try to cleanse the heart before all is lost!", sourceObjectiveStatus = "unverified-source-field" }
quests[13797] = { id = 13797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Deeds", description = "What Draaka requires is a magnet of sorts - something that her demonic missiles will be drawn to.\n\n<Durak grins slyly.>\n\nI happen to know of a method that should suit our purposes.\n\nYou scour the mines for fist-sized chunks of ore, while I prepare a special... enchantment.", sourceObjective = "Search the piles of Fresh Rubble to find 10 Chunks of Ore.", progress = "Have you collected the ore we need?", completion = "Well done! These should hold a curse long enough for our purposes....", sourceObjectiveStatus = "unverified-source-field" }
quests[13798] = { id = 13798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rain of Destruction", description = "Just in time, {class}. The elves have launched another attack!\n\nFrom the guard towers, use the accursed ore to mark targets for Draaka.\n\nHer projectiles will strike your target and erupt in fel magic flame, destroying any nearby enemies.\n\nThere is strong prejudice against the use of demonic magics. Unjustified, but real nonetheless. For this reason, I will transform you into an imp for the duration of the mission to prevent you from being identified.", sourceObjective = "Using Accursed Ore to mark targets for Draaka, you are to kill 30 Night Elf troops and 5 Raging Ancients.\n\nSpeak with Durak to reapply Imp Disguise.", progress = "Has the enemy fallen, {name}?", completion = "Did you feel it, {name}!?\n\nThe raw fel power seething through your being?\n\nThere is nothing else like it!", sourceObjectiveStatus = "unverified-source-field" }
quests[13799] = { id = 13799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Are My Keys?", description = "I can't find my keys -- I suspect my evil twin is at fault. \"Take care\" of him for me, {name}.", sourceObjective = "Dr. Fingers wants you to kill his evil clone, Evil Fingers, and retrieve his keys.", sourceObjectiveStatus = "unverified-source-field" }
quests[13801] = { id = 13801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Elves Walking", description = "D-did you hear that? Ghosts! I hate ghosts!\n\nTheir eerie howls are coming from the barrows to the south. Ahhh! Make them stop!!\n\nPlease, <mister/missy> I'll pay good money to get those voices out of my head!", sourceObjective = "Destroy any 15 of the night elf ghosts at Dor'danil Barrow Den.", completion = "Woohooo!!\n\nYou've silenced the voices! Thank you, thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[13802] = { id = 13802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Goblin with Two Brains", description = "Do you see them, along the shore? Such magnificent specimens! Look at their primitive society in action, working like a well-oiled machine from the lowliest grunt to their leader, who I've named \"King Burgrurble.\"\n\nI must study their brains.\n\nCan you procure an intact Slobberfang Murloc brain stem for me? Kill them - for science!", sourceObjective = "Bring a Slobberfang Murloc Brain Stem to Professor Flozz along the coast.", sourceObjectiveStatus = "unverified-source-field" }
quests[13803] = { id = 13803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Weak", description = "We knew the elves wouldn't go down without a fight, but no one expected them to be able to lay siege to Splintertree...\n\nTime for them to pay for their actions!\n\nNearby, in the Dor'Danil Barrow Den, lies something very dear to the enemy - the Forest Heart.\n\nI need someone to make their way to the heart and corrupt it.\n\nThat someone is you, {name}.\n\nFirst though, bring my axe to Durak here in the mines. He'll make use of the blood of our enemies.", sourceObjective = "Kadrak wants you to bring the Blood-Soaked Axe to Durak in Splintertree Post.\n\nProvided item:", completion = "Tainting the Forest's Heart?\n\nHow ruthless - an utterly vicious blow....\n\nI adore the idea!", sourceObjectiveStatus = "unverified-source-field" }
quests[13805] = { id = 13805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pierce Their Heart!", description = "There...\n\nThe blood of the fallen Kaldorei is turned. It can now be used on the Forest Heart in Dor'Danil Barrow Den. Doing so will utterly corrupt it.\n\nThe sacred relic of the arrogant elves will be turned against them. How poetic!\n\n<Durak laughs cruelly.>\n\nThe barrow den lies nestled against the hills to the southeast. One of my imps has laid a blood trail from the entrance to the heart.\n\nMake haste! Kadrak is not likely to be in a patient mood.\n\nOff you go, {class}.", sourceObjective = "Durak wants you to use the Tainted Blood of the Kaldorei on the Forest Heart.", completion = "It is done?\n\nGood work, {name}. That will gradually weaken their forces, as well as their spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13806] = { id = 13806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Duty", description = "Listen, {class}, I know this assault on Splintertree has everyone worked up, but if we forget about the satyr portals we'll come out of this crisis to face an even larger one.\n\n<Locke stares at your expressionless face.>\n\nYou don't know about the portals?\n\nTo the northeast, in the regions of Satyrnaar and Xavian, the satyrs are attempting to summon in demons to bolster their numbers.\n\nWe must be vigilant in closing those portals, no matter what issues we face here!", sourceObjective = "Locke Okarr in Splintertree wants you to close 12 Satyr Portals in Satyrnaar and Xavian.", completion = "Good work, {race}.\n\nOne less thing we have to worry about!", sourceObjectiveStatus = "unverified-source-field" }
quests[13808] = { id = 13808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Improbable", description = "I have a special mission that requires a well equipped, competent {class}. As I have no one else to spare, I suppose I'll have to settle for you...\n\nThe enemy has assaulted Warsong Lumber Camp and cut it off from the rest of our forces. An important blood elf diplomat en route to Orgrimmar is trapped there.\n\nShe must be liberated.\n\nTake the road northeast and pour this powder into the smoldering brazier to summon our operative there. Do whatever he might require of you.\n\nDismissed!", sourceObjective = "Kadrak wants you to use the Secret Signal Powder on the Smoldering Brazier across from Satyrnaar.\n\nProvided item:", completion = "You have your work cut out for you here, friend.\n\nLet's hope that you're up to the task,,,,", sourceObjectiveStatus = "unverified-source-field" }
quests[13809] = { id = 13809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat From Above", description = "Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated.\n\nOur skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", sourceObjective = "Eadric the Pure at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.", progress = "Have you defeated the Cult of the Damned raiding party?", completion = "{name}, you and your allies have spared the tournament from a devastating attack. Though our skytalon riders are brave, they  have their hands full keeping the peace on the tournament grounds and would be hard-pressed to defend the skies against the cult's attack. You have the thanks of the Argent Crusade and all who have gathered here to compete.", sourceObjectiveStatus = "unverified-source-field" }
quests[13810] = { id = 13810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Battle To The Enemy", description = "The coliseum is perched in the most dangerous part of the world, {name}. The territory we've taken from the Scourge has been paid for in blood and misery, yet the enemy continues to strike back with a seemingly limitless army. To make matters worse, this undead army is supported and assisted by mortal sympathizers, the Cult of the Damned.\n\nGo forth into Icecrown and slay any cultists you encounter.", sourceObjective = "Cellian Daybreak at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.", progress = "Have you tested yourself in combat?", completion = "You are a true champion, {name}, both inside the ring and on the field. We must all be vigilant against the Scourge and you are a great example to our brethren and your own people.", sourceObjectiveStatus = "unverified-source-field" }
quests[13811] = { id = 13811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, besting challengers of all levels. When the tournament begins, those you have defeated will have redoubled their efforts and will seek to avenge their losses.\n\nIt would be wise to continue honing your own skills and learning from your opponents. Champions representing all cities practice in the Ring of Champions. Equip your lance, mount up on any mount you're entitled to use at the stables, and face the champions.", sourceObjective = "Bring 4 Marks of the Champion to Luuri at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you finished training with the other champions?", completion = "Well done. Training against the other champions is one of the best ways to prepare yourself for tournament competition. I know you'll make the Horde proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13812] = { id = 13812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat From Above", description = "The Argent Crusade has doubled the guard since your exposure of the Cult of the Damned's infiltrator. They know the cultists won't stop until they've destroyed this area and thwarted the tournament.\n\nThe Argent Crusade's scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party.\n\nYou must intercept and destroy them before they attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", sourceObjective = "Crok Scourgebane at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.", completion = "{name}, you have spared the tournament from a devastating attack. The Argent Crusade and all who gather here are in our debt and we'll make certain they remember it. For all their bluster about providing protection, the peacekeepers and skytalons spend more time breaking up drunken brawls than keeping us safe from the Scourge.\n\nIt's no matter. We always protect our own.", sourceObjectiveStatus = "unverified-source-field" }
quests[13813] = { id = 13813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Battle To The Enemy", description = "While we all play at mock combat, it will do us good to remember that the real enemy surrounds us. The Argent Crusade wants to use competition to find the best fighters, but we can tell that by who returns from battle. Let's show the paladins that we are willing to take battle to the Cult of the Damned, even while making preparations for the tournament.\n\nGo forth into Icecrown and slay any of the cultists you encounter. They have a strong presence around Aldur'thar and Deathspeaker's Watch.", sourceObjective = "Zor'be the Bloodletter at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.", progress = "Have you tested yourself in combat?", completion = "You have done well in demonstrating our commitment to fighting the Scourge, no matter where we are or what we are doing.", sourceObjectiveStatus = "unverified-source-field" }
quests[13814] = { id = 13814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, overcoming challengers of all levels. You must make certain that you can defeat anyone you face when the tournament begins.\n\nYou should continue honing your own skills and learning more about the weaknesses of your opponents. Champions representing all cities practice in the Ring of Champions near the stables. Go to the stables, equip your lance, pick any mount you can ride, then face the champions in practice bouts.", sourceObjective = "Bring 4 Marks of the Champion to Illyrie Nightfall at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you finished training with the other champions?", completion = "You handle your mount well, {name}. In time, your competitors will learn to fear you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13815] = { id = 13815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Stumps", description = "As you've been told by now, we are to escort a diplomat from within the besieged lumber camp to safety.\n\nAs it stands, that's simply impossible. The elves have a thousand arrows trained on the camp's exits.\n\nFirst we must create a diversion - something that will take their eyes off of the camp for a time.\n\nMy idea is simple. Take this axe and cut down the trees they've been nurturing in the region.\n\nWhen you're through, use the signal powder here to speak with me again.", sourceObjective = "Krokk wants you to use the Splintertree Axe to cut down the Ashenvale Oaks in Warsong Lumber Camp.\n\nIf you lose your Secret Signal Powder, speak to Kadrak at Splintertree.", completion = "Nice work, {name}.\n\nYou've demoralized the enemy and harvested resources for the Horde.\n\nLet's hope the rest of the mission goes as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[13816] = { id = 13816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: The Celestial Planetarium", description = "Listen, <lad/lass>!  Azeroth's fate is at stake here.\n\nOur only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters.\n\nLocate the Celestial Planetarium and come back with any information you get.  We might still have some time to prepare for Algalon's arrival.", sourceObjective = "Prospector Loren at the Archivum in Ulduar wants you to locate the entrance to the Celestial Planetarium.", progress = "Did you find it, {name}?", completion = "It's locked?  Figures!\n\nI'll let Brann know... maybe he can uncover something in the Archivum.", sourceObjectiveStatus = "unverified-source-field" }
quests[13817] = { id = 13817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Archivum Data Disc", description = "This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections.  Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\"\n\nThere must be a device inside Ulduar capable of reading the disc.", sourceObjective = "Bring the Archivum Data Disc to the Archivum Console in Ulduar.", progress = "The console whirrs with energy as the round receptacle opens.", completion = "The platinum disc fits perfectly inside the console.  It begins to spin as its contents are scanned by white beams of light.", sourceObjectiveStatus = "unverified-source-field" }
quests[13818] = { id = 13818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Algalon", description = "You really did it, {name}.  Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium.\n\nYou best hurry, <lad/lass>.  Time is of the essence.", sourceObjective = "Bring the Sigils of the Watchers to the Archivum Console in Ulduar.", progress = "The console's bright lights scan the glass surface repeatedly, as if awaiting some form of input.", completion = "Stand by for verification.\n\nAccess to the Celestial Planetarium granted.  Please retrieve your key.", sourceObjectiveStatus = "unverified-source-field" }
quests[13819] = { id = 13819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: All Is Well That Ends Well", description = "We'd best hurry now, {name}.  We're going to have to transmit the reply-code from Dalaran.\n\nTake it to Rhonin, I will meet you there.", sourceObjective = "Take the Reply-Code Alpha to Rhonin in Dalaran.", progress = "You're ready, {name}?", completion = "You're here.  Let us hope this works.  For all our sakes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13820] = { id = 13820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blastbolt Brothers", description = "The highlord has tasked me with getting that coliseum completed as soon as possible. We've put our own masons to work on the project, but we found out very quickly that we were going to need help procuring materials. I've hired a couple of goblins, Bezzle Blastbolt and his brother, Bozzle.\n\nThey're supervising construction at the southeastern end of the tournament grounds. Speak with Bezzle and see if he and his brother could use any more help getting the building materials we need.", sourceObjective = "Speak with Bezzle Blastbolt at the Argent Tournament Grounds.", completion = "So the justicar sent you to see us? Good, good...\n\nWe could always use more help with the, uh, \"requisition\" of materials.", sourceObjectiveStatus = "unverified-source-field" }
quests[13821] = { id = 13821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Freya's Sigil", description = "Freya's Sigil is going to be one of the tougher ones, I reckon.\n\nAccording to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark.  Should any of the elders be harmed, the Sigil's integrity will be compromised.\n\nSparing the elders, however, means that Freya will be more powerful when you face her.\n\nWhat can I say, {name}.  We're stuck between a rock and hard place.", sourceObjective = "Prospector Loren at the Archivum in Ulduar wants you to obtain Freya's Sigil.\n\nFor more information on obtaining Freya's Sigil consult the Archivum Console.", progress = "Freya's sigil, {name}?  Do ye have it?", completion = "Excellent job, {name}.  We're one step closer to saving Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[13822] = { id = 13822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Hodir's Sigil", description = "Hodir's Sigil won't be easy to obtain.  Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it!\n\nCheck the Archivum console if you need more information.  That thing contains more knowledge than all of the world's libraries put together!", sourceObjective = "Prospector Loren at the Archivum in Ulduar wants you to obtain Hodir's Sigil.\n\nFor more information on obtaining Hodir's Sigil, consult the Archivum Console.", progress = "Did ye obtain the sigil, {name}?", completion = "Ye did it!  I don't know how, but ye did!", sourceObjectiveStatus = "unverified-source-field" }
quests[13823] = { id = 13823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Thorim's Sigil", description = "Thorim's not himself, {name}.  He's come under a dark influence.\n\nAn evil presence under the guise of an illusion pretends to be his lost wife, Sif.\n\nYe can't let him be overcome by this impostor's spell.  If he does, the location of his sigil might forever be lost!\n\nYer going to have to beat some sense into him and yer going to have to do it quick.\n\nAs always, the Archivum Console will give ye all the gory details... even the ones ye don't like.", sourceObjective = "Prospector Loren at the Archivum in Ulduar wants you to obtain Thorim's Sigil.\n\nFor more information on obtaining Thorim's Sigil consult the Archivum Console.", progress = "Well, {name}?  Do ye have it?", completion = "Ye never cease to impress, {name}.\n\nYe and me are having a pint together after all this is done, ye hear me?", sourceObjectiveStatus = "unverified-source-field" }
quests[13824] = { id = 13824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Mimiron's Sigil", description = "Mimiron's a clever one.  His entire abode is rigged with some sort of self-destruction mechanism.\n\nUnfortunately yer gonna have to race against it if ye want to get his sigil.  Check the Archivum Console for more details if ye need them.", sourceObjective = "Prospector Loren at the Ulduar Archivum wants you to obtain Mimiron's Sigil.\n\nFor more information on obtaining Mimiron's Sigil consult the Archivum Console.", progress = "Were you able to obtain the sigil, {name}?", completion = "I've got to hand it to you, {name}.  Our odds might not be the best, but I feel a lot better with you lending a hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[13825] = { id = 13825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clamlette Surprise", sourceObjective = "Hey, I remember you!  Aren't you the {class} that helped me make all that clamlette back in the day?\n\nTell you what, step on up and I'll show you my newest recipe - it's simple and delicious!", sourceObjectiveStatus = "unverified-source-field" }
quests[13826] = { id = 13826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat Pagle, Angler Extreme", sourceObjective = "Well hello there, young {race}.  Either my memory is failing me, or I forgot to give you this the last time we spoke....", sourceObjectiveStatus = "unverified-source-field" }
quests[13828] = { id = 13828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastery Of Melee", description = "The heart of tournament competition is mounted melee combat. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion.\n\nOnce you're mounted, seek out Jeran Lockwood. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Jeran will instruct you on how to use your defenses to keep you safe while attacking a melee target at close range.", sourceObjective = "Equip your lance, then mount the Stabled Quel'dorei Steed outside the pavilion. Speak to Jeran Lockwood and use Thrust 5 times on a Melee Target, then return to Arcanist Taelis at the Argent Tournament Grounds.", completion = "Keep the words of the master in mind as you practice with the training dummies.", sourceObjectiveStatus = "unverified-source-field" }
quests[13829] = { id = 13829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastery Of Melee", description = "The heart of tournament competition is mounted melee combat. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.\n\nOnce you're mounted, seek out Jeran Lockwood. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Jeran will instruct you on how to use your defenses to keep you safe while attacking a melee target at close range.", sourceObjective = "Equip your lance, then mount the Stabled Sunreaver Hawkstrider outside the pavilion. Speak to Jeran Lockwood and use Thrust 5 times on a Melee Target, then return to Magister Edien Sunhollow at the Argent Tournament Grounds.", progress = "Did you learn how to train with the melee target?", completion = "Keep the words of the master in mind as you practice with the training dummies.", sourceObjectiveStatus = "unverified-source-field" }
quests[13830] = { id = 13830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ghostfish", description = "Any Northrend angler worth <his/her> salt knows about the pygmy suckerfish.  It's not edible, but sometimes useful to alchemists.\n\nThere is, however, a stealthy fish that hides among the suckerfish in the River's Heart of Sholazar Basin.  The phantom ghostfish.  When out of water, they become increasingly translucent until they fade away completely.  Some hypothesize they return to Sholazar, and others are more... superstitious.\n\nI want you to catch this fish and discover its secret by any means!", sourceObjective = "Marcia Chase in Dalaran City wants you to discover the mystery of the Phantom Ghostfish.", progress = "Is the ghostfish haunting your best efforts?\n\n<Marcia looks particularly proud of herself for her pun.>", completion = "So eating it makes you invisible... what a strange defense this clever fish has developed.\n\nI'd like to digest this for a bit.  Pun not intended, {name}.  Really.  Why don't you come see me tomorrow?", sourceObjectiveStatus = "unverified-source-field" }
quests[13831] = { id = 13831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Troubling Prescription", description = "A crude, hastily-assembled apothecary's workbench stands here, heaped with scrawled notes and noxious brews. It looks as though the Forsaken have also been studying Foulhoof's handiwork. You grab the most important-looking notes and prepare to smash the laboratory before notifying Treetender of your discovery.", sourceObjective = "Deliver the Apothecary's notes to Tharnariun Treetender in Lor'danel.", progress = "What's this? You found something else in the cave?", completion = "<Tharnariun Treetender pages through the notes as you relate your story, the lines in his face deepening with concern.>\n\nSo the Forsaken have been studying Foulhoof's work? My gut crawls at the thought of what they might have done were they able to weaponize his corruption. You've done well to destroy their work, but this raises deeper concerns. What brought the Forsaken to our doorstep? Are they working with the Shatterspear trolls to our north? Sorrows are heaping upon sorrows, {class}. I'm glad you're here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13832] = { id = 13832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jewel Of The Sewers", description = "Hard to believe that most people fish in the Dalaran Sewers for giant rats and mutated fish.  Especially when those waters are filled with priceless jewelry - discarded by broken hearted fools, thieves, and careless drunks.\n\nThe trick is to let your hook drag the bottom and don't pull up too hard when you get something.  Try it out, {name}.  I'd be willing to trade whatever you find for a few trinkets of my own.", sourceObjective = "Marcia Chase in Dalaran City wants you to bring her a piece of Corroded Jewelry.", progress = "Any luck?", completion = "Well now, that looks like it could be valuable.  Difficult to know until it's cleaned up and appraised, but I'm still willing to make the trade if you are.", sourceObjectiveStatus = "unverified-source-field" }
quests[13833] = { id = 13833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Is Thicker", description = "The bloodtooth is a feisty little fish used in a recipe to cure infected wounds.  We could use some of them, if you're up to it.\n\nAs the name suggests, they've a hunger for blood.  The only way I know how to catch the little devils is by creating a blood pool and fishing in it.\n\nGet yourself covered in blood - just slaughter a beast in the Borean Tundra - and then jump in the water.  It'll wash right off and create the perfect fishing spot.", sourceObjective = "Marcia Chase in Dalaran City wants you to bring her 5 Bloodtooth Frenzies.", progress = "Any luck with the bloodtooth?  Don't forget what I told you about making blood pools.", completion = "You are a brave one, {name}.  I hope you didn't lose any extremities making your fishing spot.  If you've still got the fishing bug, come back tomorrow and we'll talk some more.", sourceObjectiveStatus = "unverified-source-field" }
quests[13834] = { id = 13834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerously Delicious", description = "The best fishing is often the most dangerous.  Wintergrasp boasts a bountiful catch for the brazen.\n\nIn fact, it's the only place to catch the fabled Terrorfish - a fish both lethal and delicious.  Bring me some, and we'll have something to discuss.", sourceObjective = "Marcia Chase in Dalaran City wants you to bring her 10 Terrorfish.", progress = "Be on your guard when you're after the Terrorfish.", completion = "My, my, my!  You've caught yourself some Terrorfish.  Why, that reminds me of the time...\n\n<Marcia regales you with stories of adventure and fishing for as long as you're willing to listen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13835] = { id = 13835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastery Of The Shield-Breaker", description = "You'll need to learn how to break through an opponent's defenses to succeed in mounted combat. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion.\n\nOnce you're mounted, seek out Valis Windchaser. He'll be on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Valis will teach you the basics of using a ranged shield breaker attack to make a ranged target vulnerable.", sourceObjective = "Equip your lance and mount the Stabled Quel'dorei Steed outside the pavilion. Speak to Valis Windchaser and use Shield-Breaker on 2 vulnerable Ranged Targets, then return to Scout Shalyndria at the Argent Tournament Grounds.", progress = "Have you practiced using your shield-breaker?", completion = "Commit Valis's lesson to memory, {name}. It will mean the difference between winning and losing your mounted combat matches.", sourceObjectiveStatus = "unverified-source-field" }
quests[13836] = { id = 13836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarmed!", description = "I've received word of an unfortunate accident at the Dalaran prison; a guard had his arm severed and thrown into the water by a particularly vicious inmate.\n\nOur first aid clinic promises they can reattach the arm if we bring it back.\n\nYou fish long enough in the water outside the prison, and I'd bet my favorite fishing pole that arm will surface.  Find that arm, and bring it to Olisarra the Kind here in Dalaran.  She'll know what to do.", sourceObjective = "Olisarra the Kind in Dalaran City wants you to return the Severed Arm to her.", progress = "Hi there.  Do you have something for me?", completion = "Oh, hello there {name}.  Marcia said you'd be coming by with that poor man's missing arm.\n\nShe also gave me this bag to give you as a reward.  It smells horrible, and I'm anxious to make the trade if you don't mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13837] = { id = 13837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastery Of The Charge", description = "Your strongest attack in mounted combat is undoubtedly the charge. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion.\n\nOnce you're mounted, speak with Rugan Steelbelly. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Rugan will tell you how to use this powerful ability and teach you some basic strategies.", sourceObjective = "Equip your lance and mount the Stabled Quel'dorei Steed outside the pavilion. Speak to Rugan Steelbelly and Charge 2 vulnerable Charge Targets, then return to Avareth Swiftstrike at the Argent Tournament Grounds.", progress = "Have you mastered the use of the charge?", completion = "With a teacher like Rugan, you'll be an expert at mounted combat in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13838] = { id = 13838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastery Of The Shield-Breaker", description = "You'll need to learn how to break through an opponent's defenses to succeed in mounted combat. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.\n\nOnce you're mounted, seek out Valis Windchaser. He'll be on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Valis will teach you the basics of using a ranged shield breaker attack to make a ranged target vulnerable.", sourceObjective = "Equip your lance and mount the Stabled Sunreaver Hawkstrider. Speak to Valis Windchaser and use Shield-Breaker on 2 vulnerable Ranged Targets, then return to Galathia Brightdawn at the Argent Tournament Grounds.", progress = "Have you finished practicing with the shield-breaker?", completion = "Commit Valis's lesson to memory, {name}. It will mean the difference between winning and losing your mounted combat matches.", sourceObjectiveStatus = "unverified-source-field" }
quests[13839] = { id = 13839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastery Of The Charge", description = "Your strongest attack in mounted combat is undoubtedly the charge. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.\n\nOnce you're mounted, speak with Rugan Steelbelly. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Rugan will tell you how to use this powerful ability and teach you some basic strategies.", sourceObjective = "Equip your lance and mount the Stabled Sunreaver Hawkstrider outside the pavilion. Speak to Rugan Steelbelly and Charge 2 vulnerable Charge Targets, then return to Amariel Sunsworn at the Argent Tournament Grounds.", progress = "Have you mastered the use of the charge?", completion = "With experience and practice, you will become deadly with the charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13840] = { id = 13840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "\"Cluck... cluck... cluck... BACAW!\n\nCluck... cluck... cluck.\"\n\nThe chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.", sourceObjective = "Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13841] = { id = 13841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Apologies", description = "This could be the end of me... Perhaps my actions were not thought out as well as they should have been...\n\nThe good news is that we pushed back an attack that would have otherwise meant the end of Splintertree. Let us pray that Commander Hellscream sees it that way.\n\nI am certain to be summoned to Orgrimmar to explain my actions.\n\nPlease, {name}, go ahead of me and present this letter to Garrosh.\n\nDo what you can to soften his heart towards me.", sourceObjective = "Draaka wants you to bring her Letter of Explanation to Garrosh Hellscream in Orgrimmar.\n\nProvided item:", completion = "Fools!!\n\nThis Draaka woman has allowed herself to be manipulated by a demon!\n\n<Garrosh studies you for a moment.>\n\nAnd I smell its taint on you as well, {class}....", sourceObjectiveStatus = "unverified-source-field" }
quests[13842] = { id = 13842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dread Head Redemption", description = "The demons want nothing more than for us to renew our dependence on their foul magics. That reliance can only lead to the entire orc race becoming enslaved.\n\nYou wish to see Draaka go unpunished? Then you must find the demons' pawn who has manipulated her, and destroy him!\n\nIf you do not soon return to me with the head of this being, then I shall see both yours and Draaka's hoisted upon a spike!", sourceObjective = "Speak to Durak in Splintertree Mines.", progress = "Have you brought me the head of the enemy, {race}?", completion = "Grah... very well.\n\nI'll remove the bounty I had placed upon your head. Though I am sorely tempted to end your life anyway, just on principle.\n\nBe sure that you never raise my ire again, {name}. Now, get out of my sight...", sourceObjectiveStatus = "unverified-source-field" }
quests[13843] = { id = 13843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scrapbot Construction Kit", description = "Searching the databanks of the prototype console reveals schematics for a scrapbot construction kit. With your engineering expertise, you could learn this schematic and produce scrapbot construction kits of your own.You will learn:", sourceObjective = "Interact with the Prototype Console in The Inventor's Library.", sourceObjectiveStatus = "unverified-source-field" }
quests[13844] = { id = 13844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Looting of Althalaxx", description = "Before you rejoin the battle, {class}, something urgent has come to my attention. My scouts report that the Forsaken are scouring the ruined tower of Althalaxx to our south.\n\nPrior to the assault, that bleak tower housed a fanatical arm of the Shadow Council commanded by the fallen highborne Athrikus Narassin. Narassin is long since dead, but if any of his work survives, we can't allow it out of our sight. Retrieve his research and kill the Forsaken commander who's plundering the ruins.", sourceObjective = "Locate Narassin's Tome among the ruins of Althalaxx and kill the Forsaken commander Teegan Holloway.", progress = "Narassin is no longer our concern, but if his life's work should fall to our enemies, centuries of dark wisdom could be called down onto our heads. How goes the hunt?", completion = "Let's see what we've got here.... By Elune, his notes are scrawled in a half dozen languages. What is this, blood? This archive makes my flesh seethe, but at least it's secure. It will take us some time to decipher these notes.\n\nOh - your reward? Yes, here. Nice work with those undead scavengers. Now get back to the fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[13845] = { id = 13845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealed Vial of Poison", description = "This vial of poison looks particularly dangerous.  Perhaps someone in Dalaran might be interested in it.", sourceObjective = "Bring the Sealed Vial of Poison to Alchemist Cinesra in the Dalaran Sewers.", progress = "Is that what I think it is, {class}?", completion = "You are brave to have carried this.  If even one drop were to touch your skin, you'd have died an agonizing death.\n\nAllow me to pay you for it... I can always use venom of exceptional potency.", sourceObjectiveStatus = "unverified-source-field" }
quests[13846] = { id = 13846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contributin' To The Cause", description = "The bestest of the champions come to the chapel to hear the argent confessor speak every day.\n\nYou should see how much she inspires them, {name}. Not only do they fight for the Argent Crusade, but they put a lot of money into the collection basket when I take it around.\n\nMaybe you'd like to contribute too?", sourceObjective = "Speak with Squire Artie to contribute 10 gold to the Argent Crusade's cause.", progress = "Do you want to contribute?", completion = "Thank you. I just know the crusade will put it to good use!", sourceObjectiveStatus = "unverified-source-field" }
quests[13847] = { id = 13847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Captain Joseph Holley at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", progress = "Have served alongside the crusaders in the Court of Bones?", completion = "Your bravery on the field has shown the crusaders what they already knew -- that our warriors are more than just parade ground decorations.", sourceObjectiveStatus = "unverified-source-field" }
quests[13848] = { id = 13848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad News Bear-er", description = "No reports have made it out of here since the beginning of the siege on Splintertree. By now, Commander Grimfang must be getting anxious.\n\nI am sending you to Zoram Strand to deliver our report. It's not pretty, but at least he'll have the facts.\n\nSpeak to Vhulgra when you're ready to make the trip.", sourceObjective = "Kadrak wants you to speak to Commander Grimfang in Zoram Strand.\n\nProvided item:", completion = "<Commander Grimfang's brow wrinkles as he reads the report.>\n\nThis is grim news, indeed.\n\nMay the spirits preserve them until we can fight our way to Splintertree....", sourceObjectiveStatus = "unverified-source-field" }
quests[13849] = { id = 13849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astranaar's Burning!", description = "{class}, Astranaar's burning!\n\nQuickly, take this bucket of water and put out the fires before there's nothing left!", sourceObjective = "Extinguish 15 fires.", completion = "Thank you!\n\nNow it's time to deal with the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13850] = { id = 13850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toxic Tolerance", description = "You want to ride a Venomhide? Then I've got bad news for you.\n\nThe Venomhide Ravasaurs, they're all poison: Poison blood, poison spit, poison skin. You climb on one, you fall off dead in a few hours.\n\nYou'd have to build up a resistance to their toxins before I sold you one, and that takes a long, LONG time... you'd need to be splashed with poisonous blood while fighting one numerous times. If you're really interested, the venomhides prefer the northern area of the Marshlands, northwest of here.", sourceObjective = "Mor'vek in Un'goro Crater claims that if you were poisoned by Venomhide Ravasaur blood 20 times, you could ride one without dying. Attack Venomhide Ravasaurs for a chance to be poisoned.", progress = "Still not immune, eh? Give up. It takes too long!", completion = "You did it? You actually did it?!\n\nHo ho! Stubborn as my wife, you are.", sourceObjectiveStatus = "unverified-source-field" }
quests[13851] = { id = 13851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Clara Tumblebrew at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders that we are worthy allies.", sourceObjectiveStatus = "unverified-source-field" }
quests[13852] = { id = 13852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Flickin Gearspanner at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the that we are a match for the Argent Crusade's own.", sourceObjectiveStatus = "unverified-source-field" }
quests[13853] = { id = 13853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Fire", description = "The fires are mostly contained, but we have to do something about those wind riders!\n\nQuick, {name}, you have to jump into one of our glaive throwers and return fire!", sourceObjective = "Use an Astranaar Thrower to shoot down 15 Hellscream's Hellions & their Watch Wind Riders.", completion = "We're saved! You've shot down enough of them that we should be able to handle the rest.\n\nI cannot thank you enough, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13854] = { id = 13854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Ranii at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders what they already knew -- that our warriors are more than just parade ground decorations.", sourceObjectiveStatus = "unverified-source-field" }
quests[13855] = { id = 13855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Airae Starseeker at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders that they can rely on us in the battle against the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[13856] = { id = 13856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Morah Worgsister at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", progress = "Have served alongside the crusaders in the Court of Bones?", completion = "Your bravery on the field has shown the crusaders what they already knew -- that our warriors are the best in Azeroth.", sourceObjectiveStatus = "unverified-source-field" }
quests[13857] = { id = 13857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Gahju at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders that we are fearless in the face of the Lich King's minions.", sourceObjectiveStatus = "unverified-source-field" }
quests[13858] = { id = 13858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Anka Clawhoof at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders that we are steadfast allies in the battle against the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[13859] = { id = 13859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Aneera Thuron at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, 3 Boneguard Lieutenants.", progress = "Have served alongside the crusaders in the Court of Bones?", completion = "Your bravery on the field has shown the crusaders that we are ready to face any enemy.", sourceObjectiveStatus = "unverified-source-field" }
